window.DC_TUTOR_SCRIPTS = {
"cafe":{"turns":[{"tutor":"Guten Tag! Was möchten Sie trinken?","tutor_en":"Hello! What would you like to drink?","tutor_ta":"வணக்கம்! நீங்கள் என்ன குடிக்க விரும்புகிறீர்கள்?","task_en":"Greet the waiter and order a drink.","task_ta":"பணியாளருக்கு வணக்கம் சொல்லி ஒரு பானம் ஆர்டர் செய்யுங்கள்.","goal":0,"options":[{"de":"Hallo! Einen Kaffee, bitte.","en":"Hello! A coffee, please.","ta":"வணக்கம்! ஒரு காபி, தயவுசெய்து."},{"de":"Guten Tag! Einen Tee, bitte.","en":"Hello! A tea, please.","ta":"வணக்கம்! ஒரு டீ, தயவுசெய்து."},{"de":"Guten Tag! Ich hätte gern einen Cappuccino.","en":"Hello! I would like a cappuccino.","ta":"வணக்கம்! எனக்கு ஒரு கப்புச்சினோ வேண்டும்."}],"tip":"der Kaffee / der Tee → einen (accusative). 'Ich hätte gern …' is the polite way to say 'I would like …'."},{"tutor":"Gern. Möchten Sie auch etwas essen?","tutor_en":"Sure. Would you also like something to eat?","tutor_ta":"சரி. சாப்பிடவும் ஏதாவது வேண்டுமா?","task_en":"Order something to eat.","task_ta":"சாப்பிட ஏதாவது ஆர்டர் செய்யுங்கள்.","goal":1,"options":[{"de":"Ja, ein Croissant, bitte.","en":"Yes, a croissant, please.","ta":"ஆம், ஒரு குரோசான், தயவுசெய்து."},{"de":"Ja, ich nehme ein Stück Kuchen.","en":"Yes, I'll have a piece of cake.","ta":"ஆம், நான் ஒரு துண்டு கேக் எடுத்துக்கொள்கிறேன்."},{"de":"Ja, ich hätte gern ein Käsebrötchen.","en":"Yes, I'd like a cheese roll.","ta":"ஆம், எனக்கு ஒரு சீஸ் பன் வேண்டும்."}],"tip":"das Croissant, das Stück, das Brötchen are neuter, so 'ein' does not change in the accusative. 'Ich nehme …' = I'll have …"},{"tutor":"Kommt sofort. Noch etwas?","tutor_en":"Coming right up. Anything else?","tutor_ta":"உடனே வருகிறது. வேறு ஏதாவது?","task_en":"Say that's all – or add a glass of water.","task_ta":"அவ்வளவுதான் என்று சொல்லுங்கள் – அல்லது ஒரு கிளாஸ் தண்ணீர் கேளுங்கள்.","goal":null,"options":[{"de":"Nein, danke. Das ist alles.","en":"No, thanks. That's all.","ta":"இல்லை, நன்றி. அவ்வளவுதான்."},{"de":"Ja, ein Glas Wasser, bitte.","en":"Yes, a glass of water, please.","ta":"ஆம், ஒரு கிளாஸ் தண்ணீர், தயவுசெய்து."},{"de":"Nein, danke. Im Moment nicht.","en":"No, thanks. Not at the moment.","ta":"இல்லை, நன்றி. இப்போதைக்கு வேண்டாம்."}],"tip":"'Das ist alles' = that's all. German says 'ein Glas Wasser' – no word for 'of'."},{"tutor":"Hat es Ihnen geschmeckt?","tutor_en":"Did you enjoy it?","tutor_ta":"உங்களுக்குச் சுவையாக இருந்ததா?","task_en":"Say it was good and ask how much it costs.","task_ta":"நன்றாக இருந்தது என்று சொல்லி, எவ்வளவு ஆகும் என்று கேளுங்கள்.","goal":2,"options":[{"de":"Ja, sehr gut. Was kostet das?","en":"Yes, very good. How much is it?","ta":"ஆம், மிகவும் நன்றாக இருந்தது. இது எவ்வளவு?"},{"de":"Ja, lecker! Wie viel kostet das?","en":"Yes, delicious! How much does it cost?","ta":"ஆம், சுவையாக இருந்தது! இதன் விலை எவ்வளவு?"},{"de":"Ja, danke. Was macht das zusammen?","en":"Yes, thanks. What does it come to altogether?","ta":"ஆம், நன்றி. மொத்தம் எவ்வளவு ஆகிறது?"}],"tip":"'Was kostet das?' and 'Was macht das?' both ask the price. 'zusammen' = altogether."},{"tutor":"Das macht zusammen 8,40 Euro. Zahlen Sie bar oder mit Karte?","tutor_en":"That's 8.40 euros altogether. Are you paying cash or by card?","tutor_ta":"மொத்தம் 8.40 யூரோ. பணமாகச் செலுத்துகிறீர்களா, அட்டை மூலமா?","task_en":"Pay: say how you want to pay.","task_ta":"பணம் செலுத்துங்கள்: எப்படிச் செலுத்த விரும்புகிறீர்கள் என்று சொல்லுங்கள்.","goal":3,"options":[{"de":"Mit Karte, bitte.","en":"By card, please.","ta":"அட்டை மூலம், தயவுசெய்து."},{"de":"Ich zahle bar.","en":"I'm paying cash.","ta":"நான் பணமாகச் செலுத்துகிறேன்."},{"de":"Bar, bitte. Stimmt so.","en":"Cash, please. Keep the change.","ta":"பணமாக, தயவுசெய்து. மீதியை வைத்துக்கொள்ளுங்கள்."}],"tip":"bar zahlen = pay cash, mit Karte zahlen = pay by card. 'Stimmt so' = keep the change (a tip of 5–10 % is usual)."},{"tutor":"Vielen Dank! Möchten Sie eine Quittung?","tutor_en":"Thank you very much! Would you like a receipt?","tutor_ta":"மிக்க நன்றி! உங்களுக்கு ரசீது வேண்டுமா?","task_en":"Say whether you want a receipt.","task_ta":"உங்களுக்கு ரசீது வேண்டுமா என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Ja, gern. Danke schön.","en":"Yes, please. Thank you.","ta":"ஆம், வேண்டும். மிக்க நன்றி."},{"de":"Nein, danke. Nicht nötig.","en":"No, thanks. Not necessary.","ta":"இல்லை, நன்றி. தேவையில்லை."},{"de":"Nein, danke, das brauche ich nicht.","en":"No, thanks, I don't need it.","ta":"இல்லை, நன்றி, எனக்கு அது தேவையில்லை."}],"tip":"'gern' makes a yes friendlier. In 'das brauche ich nicht' the verb stays in position 2 and 'nicht' goes to the end."},{"tutor":"Alles klar. Einen schönen Tag noch!","tutor_en":"All right. Have a nice day!","tutor_ta":"சரி. உங்கள் நாள் இனிதாக அமையட்டும்!","task_en":"Thank the waiter and say goodbye.","task_ta":"பணியாளருக்கு நன்றி சொல்லி விடைபெறுங்கள்.","goal":3,"options":[{"de":"Danke! Auf Wiedersehen!","en":"Thanks! Goodbye!","ta":"நன்றி! போய் வருகிறேன்!"},{"de":"Danke, Ihnen auch. Tschüss!","en":"Thanks, you too. Bye!","ta":"நன்றி, உங்களுக்கும் அப்படியே. பை!"},{"de":"Vielen Dank, gleichfalls. Auf Wiedersehen!","en":"Thank you very much, likewise. Goodbye!","ta":"மிக்க நன்றி, உங்களுக்கும் அப்படியே. போய் வருகிறேன்!"}],"tip":"'Ihnen auch' and 'gleichfalls' both mean 'you too'. 'Auf Wiedersehen' is polite, 'Tschüss' is casual."}],"end":"Auf Wiedersehen und bis bald!","end_en":"Goodbye and see you soon!","end_ta":"போய் வாருங்கள், விரைவில் சந்திப்போம்!","words":[{"de":"der Kaffee","en":"the coffee"},{"de":"das Stück Kuchen","en":"the piece of cake"},{"de":"Ich hätte gern …","en":"I would like …"},{"de":"Was kostet das?","en":"How much is it?"},{"de":"bar zahlen","en":"to pay cash"},{"de":"mit Karte zahlen","en":"to pay by card"},{"de":"die Quittung","en":"the receipt"},{"de":"Stimmt so.","en":"Keep the change."}]},
"vorstellen":{"turns":[{"tutor":"Hallo! Ich bin Lena, ich wohne im zweiten Stock. Und wie heißt du?","tutor_en":"Hi! I'm Lena, I live on the second floor. And what's your name?","tutor_ta":"ஹலோ! நான் லேனா, நான் இரண்டாவது மாடியில் வசிக்கிறேன். உன் பெயர் என்ன?","task_en":"Say hello and tell her your name (use your own name).","task_ta":"வணக்கம் சொல்லி உங்கள் பெயரைச் சொல்லுங்கள் (உங்கள் சொந்தப் பெயரைப் பயன்படுத்துங்கள்).","goal":0,"options":[{"de":"Hallo! Ich heiße Arun.","en":"Hi! My name is Arun.","ta":"ஹலோ! என் பெயர் அருண்."},{"de":"Hi Lena! Ich bin Priya.","en":"Hi Lena! I'm Priya.","ta":"ஹாய் லேனா! நான் பிரியா."},{"de":"Hallo! Mein Name ist Karthik. Freut mich!","en":"Hi! My name is Karthik. Nice to meet you!","ta":"ஹலோ! என் பெயர் கார்த்திக். சந்தித்ததில் மகிழ்ச்சி!"}],"tip":"Three ways to give your name: Ich heiße …, Ich bin …, Mein Name ist … 'Freut mich!' = nice to meet you."},{"tutor":"Freut mich! Woher kommst du?","tutor_en":"Nice to meet you! Where are you from?","tutor_ta":"சந்தித்ததில் மகிழ்ச்சி! நீ எங்கிருந்து வருகிறாய்?","task_en":"Say where you come from.","task_ta":"நீங்கள் எங்கிருந்து வருகிறீர்கள் என்று சொல்லுங்கள்.","goal":1,"options":[{"de":"Ich komme aus Indien.","en":"I come from India.","ta":"நான் இந்தியாவிலிருந்து வருகிறேன்."},{"de":"Ich komme aus Chennai, in Indien.","en":"I'm from Chennai, in India.","ta":"நான் இந்தியாவில் உள்ள சென்னையிலிருந்து வருகிறேன்."},{"de":"Ich bin aus Indien, aus Tamil Nadu.","en":"I'm from India, from Tamil Nadu.","ta":"நான் இந்தியாவிலிருந்து, தமிழ்நாட்டிலிருந்து வருகிறேன்."}],"tip":"kommen aus + country/city: Ich komme aus Indien. Most countries have no article – exceptions: aus der Türkei, aus den USA."},{"tutor":"Oh, toll! Und was machst du beruflich?","tutor_en":"Oh, great! And what do you do for a living?","tutor_ta":"ஓ, அருமை! நீ என்ன வேலை செய்கிறாய்?","task_en":"Say what you do for work (or what you study).","task_ta":"நீங்கள் என்ன வேலை செய்கிறீர்கள் (அல்லது என்ன படிக்கிறீர்கள்) என்று சொல்லுங்கள்.","goal":2,"options":[{"de":"Ich bin Ingenieur.","en":"I'm an engineer.","ta":"நான் ஒரு பொறியாளர்."},{"de":"Ich arbeite in einem Krankenhaus.","en":"I work in a hospital.","ta":"நான் ஒரு மருத்துவமனையில் வேலை செய்கிறேன்."},{"de":"Ich studiere Informatik an der Uni.","en":"I study computer science at university.","ta":"நான் பல்கலைக்கழகத்தில் கணினி அறிவியல் படிக்கிறேன்."}],"tip":"No article before jobs: Ich bin Ingenieur (not 'ein Ingenieur'). Women often add -in: Ingenieurin."},{"tutor":"Interessant! Und seit wann wohnst du hier?","tutor_en":"Interesting! And how long have you been living here?","tutor_ta":"சுவாரஸ்யம்! நீ இங்கே எவ்வளவு காலமாக வசிக்கிறாய்?","task_en":"Say how long you have lived here.","task_ta":"நீங்கள் இங்கே எவ்வளவு காலமாக வசிக்கிறீர்கள் என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Seit einer Woche.","en":"For a week.","ta":"ஒரு வாரமாக."},{"de":"Ich wohne erst seit Montag hier.","en":"I've only lived here since Monday.","ta":"நான் திங்கள்கிழமையிலிருந்துதான் இங்கே வசிக்கிறேன்."},{"de":"Seit zwei Monaten. Die Wohnung ist schön.","en":"For two months. The flat is nice.","ta":"இரண்டு மாதங்களாக. வீடு நன்றாக இருக்கிறது."}],"tip":"seit + dative + PRESENT tense = for/since: seit einer Woche, seit zwei Monaten. 'erst' = only (so far)."},{"tutor":"Dann herzlich willkommen im Haus!","tutor_en":"Then a warm welcome to the building!","tutor_ta":"அப்படியானால் இந்தக் கட்டிடத்துக்கு அன்புடன் வரவேற்கிறேன்!","task_en":"Thank her and ask Lena a question about herself.","task_ta":"நன்றி சொல்லி, லேனாவிடம் அவளைப் பற்றி ஒரு கேள்வி கேளுங்கள்.","goal":3,"options":[{"de":"Danke! Und was machst du?","en":"Thanks! And what do you do?","ta":"நன்றி! நீ என்ன செய்கிறாய்?"},{"de":"Danke! Woher kommst du, Lena?","en":"Thanks! Where are you from, Lena?","ta":"நன்றி! லேனா, நீ எங்கிருந்து வருகிறாய்?"},{"de":"Danke! Wohnst du schon lange hier?","en":"Thanks! Have you lived here long?","ta":"நன்றி! நீ இங்கே நீண்ட காலமாக வசிக்கிறாயா?"}],"tip":"In a du-question the verb ends in -st and comes first (or after the question word): Wohnst du …? Woher kommst du?"},{"tutor":"Ich komme aus Hamburg, bin Lehrerin und wohne seit fünf Jahren hier. Hast du noch Fragen?","tutor_en":"I'm from Hamburg, I'm a teacher and I've lived here for five years. Do you have any other questions?","tutor_ta":"நான் ஹாம்பர்க்கிலிருந்து வருகிறேன், நான் ஒரு ஆசிரியை, இங்கே ஐந்து வருடங்களாக வசிக்கிறேன். உனக்கு வேறு ஏதாவது கேள்விகள் இருக்கிறதா?","task_en":"Ask where something is nearby (supermarket, bus stop, pharmacy).","task_ta":"அருகில் ஏதாவது எங்கே இருக்கிறது என்று கேளுங்கள் (சூப்பர்மார்க்கெட், பேருந்து நிறுத்தம், மருந்தகம்).","goal":3,"options":[{"de":"Ja! Wo ist hier ein Supermarkt?","en":"Yes! Where is a supermarket around here?","ta":"ஆம்! இங்கே சூப்பர்மார்க்கெட் எங்கே இருக்கிறது?"},{"de":"Ja. Wo ist die Bushaltestelle?","en":"Yes. Where is the bus stop?","ta":"ஆம். பேருந்து நிறுத்தம் எங்கே?"},{"de":"Ja, gibt es hier eine Apotheke?","en":"Yes, is there a pharmacy here?","ta":"ஆம், இங்கே மருந்தகம் இருக்கிறதா?"}],"tip":"'Wo ist …?' = where is …? 'Gibt es …?' = is there …? – 'es gibt' takes the accusative: eine Apotheke, einen Supermarkt."},{"tutor":"Das ist ganz nah, nur fünf Minuten zu Fuß. Ich zeige es dir gern!","tutor_en":"It's very close, only five minutes on foot. I'm happy to show you!","tutor_ta":"அது மிக அருகில் இருக்கிறது, நடந்தால் ஐந்து நிமிடம்தான். நான் உனக்குக் காட்டுகிறேன்!","task_en":"Thank her and say goodbye.","task_ta":"அவளுக்கு நன்றி சொல்லி விடைபெறுங்கள்.","goal":null,"options":[{"de":"Danke, das ist nett!","en":"Thanks, that's kind of you!","ta":"நன்றி, நீ மிகவும் அன்பானவள்!"},{"de":"Super, danke! Bis bald, Lena!","en":"Great, thanks! See you soon, Lena!","ta":"அருமை, நன்றி! விரைவில் சந்திப்போம், லேனா!"},{"de":"Vielen Dank! Einen schönen Abend noch!","en":"Thanks a lot! Have a nice evening!","ta":"மிக்க நன்றி! இனிய மாலையாக அமையட்டும்!"}],"tip":"'Bis bald' = see you soon. 'Einen schönen Abend noch!' is a friendly goodbye in the evening."}],"end":"Gern! Tschüss und bis bald!","end_en":"You're welcome! Bye and see you soon!","end_ta":"மகிழ்ச்சி! பை, விரைவில் சந்திப்போம்!","words":[{"de":"der Nachbar / die Nachbarin","en":"the neighbour"},{"de":"Ich heiße …","en":"My name is …"},{"de":"Ich komme aus …","en":"I come from …"},{"de":"Was machst du beruflich?","en":"What do you do for a living?"},{"de":"der Stock","en":"the floor (storey)"},{"de":"Freut mich!","en":"Nice to meet you!"},{"de":"seit","en":"since / for (time)"},{"de":"zu Fuß","en":"on foot"}]},
"supermarkt":{"turns":[{"tutor":"Guten Tag! Kann ich Ihnen helfen?","tutor_en":"Hello! Can I help you?","tutor_ta":"வணக்கம்! நான் உங்களுக்கு உதவலாமா?","task_en":"Ask where you can find a product (e.g. rice, milk, spices).","task_ta":"ஒரு பொருள் எங்கே கிடைக்கும் என்று கேளுங்கள் (எ.கா. அரிசி, பால், மசாலா).","goal":0,"options":[{"de":"Ja, wo ist der Reis?","en":"Yes, where is the rice?","ta":"ஆம், அரிசி எங்கே இருக்கிறது?"},{"de":"Ja, bitte. Wo finde ich Milch?","en":"Yes, please. Where can I find milk?","ta":"ஆம், தயவுசெய்து. பால் எங்கே கிடைக்கும்?"},{"de":"Entschuldigung, haben Sie auch Gewürze?","en":"Excuse me, do you have spices too?","ta":"மன்னிக்கவும், உங்களிடம் மசாலாப் பொருட்களும் இருக்கிறதா?"}],"tip":"'Wo finde ich …?' = where can I find …? Milk, rice etc. often need no article: Wo finde ich Milch?"},{"tutor":"Ja, natürlich. In Gang drei, ganz hinten links.","tutor_en":"Yes, of course. In aisle three, right at the back on the left.","tutor_ta":"ஆம், நிச்சயமாக. மூன்றாவது வரிசையில், கடைசியில் இடது பக்கம்.","task_en":"Repeat the aisle to check, and say thank you.","task_ta":"சரிபார்க்க வரிசை எண்ணைத் திரும்பச் சொல்லி, நன்றி சொல்லுங்கள்.","goal":2,"options":[{"de":"Gang drei? Danke schön!","en":"Aisle three? Thank you!","ta":"மூன்றாவது வரிசையா? மிக்க நன்றி!"},{"de":"Ganz hinten links? Vielen Dank!","en":"Right at the back on the left? Thanks a lot!","ta":"கடைசியில் இடது பக்கமா? மிக்க நன்றி!"},{"de":"Also Gang drei, links. Danke für die Hilfe!","en":"So aisle three, on the left. Thanks for the help!","ta":"அப்படியானால் மூன்றாவது வரிசை, இடது பக்கம். உதவிக்கு நன்றி!"}],"tip":"Repeating as a question is a good way to check you understood. 'für' + accusative: für die Hilfe."},{"tutor":"Na, haben Sie alles gefunden?","tutor_en":"So, did you find everything?","tutor_ta":"சரி, எல்லாம் கிடைத்ததா?","task_en":"Say yes, but ask for a bigger size or another kind.","task_ta":"ஆம் என்று சொல்லுங்கள், ஆனால் பெரிய அளவு அல்லது வேறு வகை கேளுங்கள்.","goal":1,"options":[{"de":"Ja, aber gibt es eine größere Packung?","en":"Yes, but is there a bigger pack?","ta":"ஆம், ஆனால் பெரிய பாக்கெட் இருக்கிறதா?"},{"de":"Fast. Haben Sie das auch in groß?","en":"Almost. Do you have this in a big size too?","ta":"கிட்டத்தட்ட. இது பெரிய அளவிலும் இருக்கிறதா?"},{"de":"Ja, danke. Gibt es auch eine andere Sorte?","en":"Yes, thanks. Is there another kind too?","ta":"ஆம், நன்றி. வேறு வகையும் இருக்கிறதா?"}],"tip":"groß → größer (bigger): eine größere Packung. 'die Sorte' = kind/variety."},{"tutor":"Leider nicht im Regal. Soll ich im Lager nachschauen?","tutor_en":"Unfortunately not on the shelf. Shall I check in the stockroom?","tutor_ta":"துரதிர்ஷ்டவசமாக அலமாரியில் இல்லை. நான் கிடங்கில் பார்க்கட்டுமா?","task_en":"Say yes, please.","task_ta":"ஆம், தயவுசெய்து என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Ja, gern. Danke!","en":"Yes, please. Thanks!","ta":"ஆம், சரி. நன்றி!"},{"de":"Ja, bitte, das ist nett.","en":"Yes, please, that's kind.","ta":"ஆம், தயவுசெய்து, அது உங்கள் அன்பு."},{"de":"Oh ja, das wäre super!","en":"Oh yes, that would be great!","ta":"ஓ ஆம், அது மிகவும் நன்றாக இருக்கும்!"}],"tip":"'Das wäre super' = that would be great ('wäre' = would be, very polite)."},{"tutor":"Hier, bitte. Das ist die letzte Packung.","tutor_en":"Here you are. This is the last pack.","tutor_ta":"இதோ. இதுதான் கடைசி பாக்கெட்.","task_en":"Ask about the price.","task_ta":"விலையைப் பற்றிக் கேளுங்கள்.","goal":null,"options":[{"de":"Super! Was kostet das?","en":"Great! How much is it?","ta":"அருமை! இது எவ்வளவு?"},{"de":"Danke! Wie viel kostet die Packung?","en":"Thanks! How much is the pack?","ta":"நன்றி! இந்த பாக்கெட்டின் விலை எவ்வளவு?"},{"de":"Toll! Ist das im Angebot?","en":"Great! Is it on offer?","ta":"அருமை! இது தள்ளுபடியில் இருக்கிறதா?"}],"tip":"'im Angebot' = on special offer. Watch for 'Angebot' signs in German supermarkets!"},{"tutor":"Heute ist sie im Angebot: nur 3,49 Euro.","tutor_en":"It's on offer today: only 3.49 euros.","tutor_ta":"இன்று இது தள்ளுபடியில் இருக்கிறது: 3.49 யூரோ மட்டுமே.","task_en":"Thank the employee for the help.","task_ta":"உதவிக்கு ஊழியருக்கு நன்றி சொல்லுங்கள்.","goal":2,"options":[{"de":"Super, vielen Dank!","en":"Great, thanks a lot!","ta":"அருமை, மிக்க நன்றி!"},{"de":"Danke schön für Ihre Hilfe!","en":"Thank you for your help!","ta":"உங்கள் உதவிக்கு மிக்க நன்றி!"},{"de":"Vielen Dank, Sie sind sehr nett!","en":"Thanks a lot, you're very kind!","ta":"மிக்க நன்றி, நீங்கள் மிகவும் அன்பானவர்!"}],"tip":"'für' + accusative: für Ihre Hilfe. 'Sie sind sehr nett' = you're very kind."},{"tutor":"Gern geschehen! Brauchen Sie noch etwas?","tutor_en":"You're welcome! Do you need anything else?","tutor_ta":"மகிழ்ச்சி! உங்களுக்கு வேறு ஏதாவது தேவையா?","task_en":"Say no and say goodbye.","task_ta":"இல்லை என்று சொல்லி விடைபெறுங்கள்.","goal":null,"options":[{"de":"Nein, danke. Tschüss!","en":"No, thanks. Bye!","ta":"இல்லை, நன்றி. பை!"},{"de":"Nein, das ist alles. Auf Wiedersehen!","en":"No, that's all. Goodbye!","ta":"இல்லை, அவ்வளவுதான். போய் வருகிறேன்!"},{"de":"Nein, danke. Schönen Tag noch!","en":"No, thanks. Have a nice day!","ta":"இல்லை, நன்றி. உங்கள் நாள் இனிதாக அமையட்டும்!"}],"tip":"'Schönen Tag noch!' is short for 'Einen schönen Tag noch!' – a very common goodbye in shops."}],"end":"Alles klar. Die Kasse ist dort vorne. Auf Wiedersehen!","end_en":"All right. The checkout is over there at the front. Goodbye!","end_ta":"சரி. பணம் செலுத்தும் இடம் அங்கே முன்னால் இருக்கிறது. போய் வாருங்கள்!","words":[{"de":"der Gang","en":"the aisle"},{"de":"das Regal","en":"the shelf"},{"de":"die Packung","en":"the pack"},{"de":"die Größe","en":"the size"},{"de":"die Sorte","en":"the kind, variety"},{"de":"im Angebot","en":"on offer"},{"de":"das Lager","en":"the stockroom"},{"de":"die Kasse","en":"the checkout"}]},
"bahnhof":{"turns":[{"tutor":"Guten Tag! Wohin möchten Sie fahren?","tutor_en":"Hello! Where would you like to go?","tutor_ta":"வணக்கம்! நீங்கள் எங்கே பயணம் செய்ய விரும்புகிறீர்கள்?","task_en":"Say where you want to travel to.","task_ta":"நீங்கள் எங்கே பயணம் செய்ய விரும்புகிறீர்கள் என்று சொல்லுங்கள்.","goal":0,"options":[{"de":"Nach München, bitte.","en":"To Munich, please.","ta":"மியூனிக்குக்கு, தயவுசெய்து."},{"de":"Ich möchte nach Hamburg fahren.","en":"I'd like to go to Hamburg.","ta":"நான் ஹாம்பர்க்குக்குப் போக விரும்புகிறேன்."},{"de":"Eine Fahrkarte nach Köln, bitte.","en":"A ticket to Cologne, please.","ta":"கொலோனுக்கு ஒரு டிக்கெட், தயவுசெய்து."}],"tip":"nach + city (no article) = to: nach München. With 'möchten' the infinitive goes to the end: … fahren."},{"tutor":"Gern. Möchten Sie heute fahren?","tutor_en":"Sure. Would you like to travel today?","tutor_ta":"சரி. நீங்கள் இன்று பயணம் செய்ய விரும்புகிறீர்களா?","task_en":"Say yes and when you want to travel.","task_ta":"ஆம் என்று சொல்லி, எப்போது பயணம் செய்ய விரும்புகிறீர்கள் என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Ja, heute, bitte.","en":"Yes, today, please.","ta":"ஆம், இன்றே, தயவுசெய்து."},{"de":"Ja, heute Nachmittag, bitte.","en":"Yes, this afternoon, please.","ta":"ஆம், இன்று பிற்பகல், தயவுசெய்து."},{"de":"Ja, so schnell wie möglich.","en":"Yes, as soon as possible.","ta":"ஆம், முடிந்தவரை சீக்கிரம்."}],"tip":"heute Nachmittag = this afternoon. 'so schnell wie möglich' = as soon as possible."},{"tutor":"Einen Moment … Ja, da gibt es einen ICE. Möchten Sie hin und zurück?","tutor_en":"One moment … Yes, there's an ICE. Would you like a return ticket?","tutor_ta":"ஒரு நிமிடம் … ஆம், ஒரு ICE ரயில் இருக்கிறது. போக வர டிக்கெட் வேண்டுமா?","task_en":"Say one-way or return, and ask when the train leaves.","task_ta":"ஒரு வழியா போக வரவா என்று சொல்லி, ரயில் எப்போது புறப்படும் என்று கேளுங்கள்.","goal":1,"options":[{"de":"Nur hin. Wann fährt der Zug?","en":"Just one way. When does the train leave?","ta":"போக மட்டும். ரயில் எப்போது புறப்படுகிறது?"},{"de":"Einfach, bitte. Wann fährt der Zug ab?","en":"One-way, please. When does the train depart?","ta":"ஒரு வழி மட்டும், தயவுசெய்து. ரயில் எப்போது புறப்படும்?"},{"de":"Hin und zurück, bitte. Wann fährt er ab?","en":"Return, please. When does it depart?","ta":"போக வர, தயவுசெய்து. அது எப்போது புறப்படும்?"}],"tip":"abfahren is separable: Der Zug fährt um 14 Uhr ab. 'einfach' / 'nur hin' = one-way, 'hin und zurück' = return."},{"tutor":"Der nächste Zug fährt um 14:32 Uhr.","tutor_en":"The next train leaves at 2:32 pm.","tutor_ta":"அடுத்த ரயில் பிற்பகல் 2:32 மணிக்குப் புறப்படும்.","task_en":"Ask which platform the train leaves from.","task_ta":"ரயில் எந்த நடைமேடையிலிருந்து புறப்படும் என்று கேளுங்கள்.","goal":2,"options":[{"de":"Von welchem Gleis?","en":"From which platform?","ta":"எந்த நடைமேடையிலிருந்து?"},{"de":"Gut. Von welchem Gleis fährt er ab?","en":"Good. Which platform does it leave from?","ta":"சரி. அது எந்த நடைமேடையிலிருந்து புறப்படும்?"},{"de":"Super. Und wo fährt der Zug ab?","en":"Great. And where does the train leave from?","ta":"அருமை. ரயில் எங்கிருந்து புறப்படுகிறது?"}],"tip":"das Gleis = platform (track). After 'von' use the dative: von welchem Gleis."},{"tutor":"Von Gleis 7. Haben Sie eine BahnCard?","tutor_en":"From platform 7. Do you have a BahnCard?","tutor_ta":"7வது நடைமேடையிலிருந்து. உங்களிடம் பான்கார்டு இருக்கிறதா?","task_en":"Say that you don't have a BahnCard.","task_ta":"உங்களிடம் பான்கார்டு இல்லை என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Nein, leider nicht.","en":"No, unfortunately not.","ta":"இல்லை, துரதிர்ஷ்டவசமாக இல்லை."},{"de":"Nein. Was ist eine BahnCard?","en":"No. What is a BahnCard?","ta":"இல்லை. பான்கார்டு என்றால் என்ன?"},{"de":"Nein, ich habe keine BahnCard.","en":"No, I don't have a BahnCard.","ta":"இல்லை, என்னிடம் பான்கார்டு இல்லை."}],"tip":"kein/keine = not a / no: Ich habe keine BahnCard (die BahnCard → keine)."},{"tutor":"Mit einer BahnCard ist es billiger. Ohne BahnCard kostet Ihre Fahrkarte 89 Euro.","tutor_en":"With a BahnCard it's cheaper. Without a BahnCard your ticket costs 89 euros.","tutor_ta":"பான்கார்டு இருந்தால் மலிவாக இருக்கும். பான்கார்டு இல்லாமல் உங்கள் டிக்கெட் 89 யூரோ.","task_en":"Buy the ticket and say how you pay.","task_ta":"டிக்கெட்டை வாங்கி, எப்படிப் பணம் செலுத்துகிறீர்கள் என்று சொல்லுங்கள்.","goal":3,"options":[{"de":"Okay. Mit Karte, bitte.","en":"Okay. By card, please.","ta":"சரி. அட்டை மூலம், தயவுசெய்து."},{"de":"Gut, ich nehme die Fahrkarte.","en":"Good, I'll take the ticket.","ta":"சரி, நான் அந்த டிக்கெட்டை வாங்குகிறேன்."},{"de":"In Ordnung. Ich zahle bar.","en":"All right. I'll pay cash.","ta":"சரி. நான் பணமாகச் செலுத்துகிறேன்."}],"tip":"'Ich nehme …' = I'll take … 'In Ordnung' = all right. The BahnCard gives a discount on train tickets."},{"tutor":"Danke schön. Hier ist Ihre Fahrkarte. Möchten Sie auch eine Sitzplatzreservierung?","tutor_en":"Thank you. Here is your ticket. Would you also like a seat reservation?","tutor_ta":"நன்றி. இதோ உங்கள் டிக்கெட். உங்களுக்கு இருக்கை முன்பதிவும் வேண்டுமா?","task_en":"Answer: do you want a seat reservation?","task_ta":"பதில் சொல்லுங்கள்: உங்களுக்கு இருக்கை முன்பதிவு வேண்டுமா?","goal":null,"options":[{"de":"Nein, danke. Das ist alles.","en":"No, thanks. That's all.","ta":"இல்லை, நன்றி. அவ்வளவுதான்."},{"de":"Ja, bitte, einen Fensterplatz.","en":"Yes, please, a window seat.","ta":"ஆம், தயவுசெய்து, ஜன்னல் ஓர இருக்கை."},{"de":"Ja, gern. Einen Platz am Gang.","en":"Yes, please. An aisle seat.","ta":"ஆம், சரி. நடைபாதை ஓர இருக்கை."}],"tip":"der Fensterplatz = window seat, der Platz am Gang = aisle seat. Both masculine → einen (accusative)."}],"end":"Alles klar. Also: Gleis 7, um 14:32 Uhr. Gute Reise!","end_en":"All right. So: platform 7, at 2:32 pm. Have a good trip!","end_ta":"சரி. அப்படியானால்: 7வது நடைமேடை, பிற்பகல் 2:32 மணிக்கு. இனிய பயணம்!","words":[{"de":"die Fahrkarte","en":"the ticket"},{"de":"das Gleis","en":"the platform"},{"de":"der Zug","en":"the train"},{"de":"abfahren","en":"to depart"},{"de":"hin und zurück","en":"return (round trip)"},{"de":"einfach","en":"one-way"},{"de":"die Sitzplatzreservierung","en":"the seat reservation"},{"de":"der Fensterplatz","en":"the window seat"}]},
"arzt":{"turns":[{"tutor":"Guten Tag! Bitte setzen Sie sich. Was fehlt Ihnen denn?","tutor_en":"Hello! Please have a seat. What seems to be the problem?","tutor_ta":"வணக்கம்! தயவுசெய்து உட்காருங்கள். உங்களுக்கு என்ன பிரச்சினை?","task_en":"Describe your symptoms.","task_ta":"உங்கள் உடல்நலப் பிரச்சினைகளை விவரியுங்கள்.","goal":0,"options":[{"de":"Ich habe Halsschmerzen und Fieber.","en":"I have a sore throat and a fever.","ta":"எனக்குத் தொண்டை வலியும் காய்ச்சலும் இருக்கிறது."},{"de":"Mir ist schlecht und ich habe Bauchschmerzen.","en":"I feel sick and I have a stomach ache.","ta":"எனக்குக் குமட்டலாக இருக்கிறது, வயிற்று வலியும் இருக்கிறது."},{"de":"Ich habe starke Kopfschmerzen und bin sehr müde.","en":"I have a bad headache and I'm very tired.","ta":"எனக்குக் கடுமையான தலைவலி, மிகவும் சோர்வாகவும் இருக்கிறது."}],"tip":"Body part + -schmerzen: Kopf-, Hals-, Bauchschmerzen (usually plural). 'Mir ist schlecht' = I feel sick (dative!)."},{"tutor":"Oh, das tut mir leid. Seit wann haben Sie die Beschwerden?","tutor_en":"Oh, I'm sorry. How long have you had these symptoms?","tutor_ta":"ஓ, வருந்துகிறேன். இந்தப் பிரச்சினைகள் எப்போதிலிருந்து இருக்கின்றன?","task_en":"Say how long you have had them.","task_ta":"அவை எப்போதிலிருந்து இருக்கின்றன என்று சொல்லுங்கள்.","goal":1,"options":[{"de":"Seit drei Tagen.","en":"For three days.","ta":"மூன்று நாட்களாக."},{"de":"Seit gestern Abend.","en":"Since yesterday evening.","ta":"நேற்று மாலையிலிருந்து."},{"de":"Seit Montag. Es wird immer schlimmer.","en":"Since Monday. It's getting worse and worse.","ta":"திங்கள்கிழமையிலிருந்து. அது மேலும் மேலும் மோசமாகிறது."}],"tip":"seit + dative: seit drei Tagen (dative plural adds -n). 'immer schlimmer' = worse and worse."},{"tutor":"Haben Sie schon etwas dagegen genommen?","tutor_en":"Have you already taken anything for it?","tutor_ta":"இதற்கு நீங்கள் ஏற்கனவே ஏதாவது எடுத்துக்கொண்டீர்களா?","task_en":"Say whether you have taken anything.","task_ta":"நீங்கள் ஏதாவது எடுத்துக்கொண்டீர்களா என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Nein, noch nichts.","en":"No, nothing yet.","ta":"இல்லை, இன்னும் எதுவும் இல்லை."},{"de":"Ja, ich habe Paracetamol genommen.","en":"Yes, I took paracetamol.","ta":"ஆம், நான் பாராசிட்டமால் எடுத்துக்கொண்டேன்."},{"de":"Nur Tee mit Ingwer und Honig.","en":"Just tea with ginger and honey.","ta":"இஞ்சியும் தேனும் கலந்த டீ மட்டும்."}],"tip":"Perfekt with haben: ich habe … genommen (nehmen → genommen). 'noch nichts' = nothing yet."},{"tutor":"Ich habe Sie untersucht. Es ist ein Virusinfekt, nichts Schlimmes.","tutor_en":"I've examined you. It's a viral infection, nothing serious.","tutor_ta":"நான் உங்களைப் பரிசோதித்தேன். இது ஒரு வைரஸ் தொற்று, பயப்பட ஒன்றுமில்லை.","task_en":"Ask what you should do now.","task_ta":"இப்போது நீங்கள் என்ன செய்ய வேண்டும் என்று கேளுங்கள்.","goal":2,"options":[{"de":"Was soll ich jetzt machen?","en":"What should I do now?","ta":"நான் இப்போது என்ன செய்ய வேண்டும்?"},{"de":"Zum Glück! Brauche ich Medikamente?","en":"Thank goodness! Do I need medicine?","ta":"நல்லவேளை! எனக்கு மருந்து தேவையா?"},{"de":"Was kann ich tun, damit es besser wird?","en":"What can I do so that it gets better?","ta":"குணமாக நான் என்ன செய்யலாம்?"}],"tip":"'sollen' asks for advice: Was soll ich machen? 'damit' sends the verb to the end: damit es besser wird."},{"tutor":"Ruhen Sie sich aus und trinken Sie viel. Ich schreibe Ihnen auch ein Rezept.","tutor_en":"Get some rest and drink plenty. I'll also write you a prescription.","tutor_ta":"ஓய்வெடுங்கள், நிறைய குடியுங்கள். உங்களுக்கு ஒரு மருந்துச்சீட்டும் எழுதித் தருகிறேன்.","task_en":"Ask for a sick note for your employer.","task_ta":"உங்கள் வேலைக்காக மருத்துவ விடுப்புச் சான்றிதழ் கேளுங்கள்.","goal":3,"options":[{"de":"Können Sie mich krankschreiben?","en":"Can you sign me off sick?","ta":"எனக்கு மருத்துவ விடுப்புச் சான்றிதழ் தர முடியுமா?"},{"de":"Danke. Kann ich eine Krankmeldung bekommen?","en":"Thanks. Can I get a sick note?","ta":"நன்றி. எனக்கு ஒரு மருத்துவ விடுப்புச் சான்றிதழ் கிடைக்குமா?"},{"de":"Ich brauche eine Krankmeldung für die Arbeit.","en":"I need a sick note for work.","ta":"எனக்கு வேலைக்காக ஒரு மருத்துவ விடுப்புச் சான்றிதழ் தேவை."}],"tip":"krankschreiben is separable: Ich schreibe Sie krank. The official word for the sick note is 'Arbeitsunfähigkeitsbescheinigung' (AU)."},{"tutor":"Ja, natürlich. Ich schreibe Sie bis Freitag krank.","tutor_en":"Yes, of course. I'll sign you off sick until Friday.","tutor_ta":"ஆம், நிச்சயமாக. வெள்ளிக்கிழமை வரை உங்களுக்கு மருத்துவ விடுப்பு தருகிறேன்.","task_en":"Ask what to do if it doesn't get better.","task_ta":"குணமாகவில்லை என்றால் என்ன செய்ய வேண்டும் என்று கேளுங்கள்.","goal":2,"options":[{"de":"Gut. Muss ich wiederkommen?","en":"Good. Do I have to come back?","ta":"சரி. நான் மீண்டும் வர வேண்டுமா?"},{"de":"Danke. Und wenn es nicht besser wird?","en":"Thanks. And if it doesn't get better?","ta":"நன்றி. குணமாகவில்லை என்றால்?"},{"de":"Perfekt. Soll ich nächste Woche wiederkommen?","en":"Perfect. Should I come back next week?","ta":"சரி. நான் அடுத்த வாரம் மீண்டும் வர வேண்டுமா?"}],"tip":"wiederkommen is separable: Ich komme wieder. 'wenn' sends the verb to the end: wenn es nicht besser wird."},{"tutor":"Wenn es bis Freitag nicht besser ist, kommen Sie bitte wieder. Gute Besserung!","tutor_en":"If it isn't better by Friday, please come back. Get well soon!","tutor_ta":"வெள்ளிக்கிழமைக்குள் குணமாகவில்லை என்றால், தயவுசெய்து மீண்டும் வாருங்கள். விரைவில் குணமடையுங்கள்!","task_en":"Thank the doctor and say goodbye.","task_ta":"மருத்துவருக்கு நன்றி சொல்லி விடைபெறுங்கள்.","goal":null,"options":[{"de":"Vielen Dank! Auf Wiedersehen.","en":"Thank you very much! Goodbye.","ta":"மிக்க நன்றி! போய் வருகிறேன்."},{"de":"Danke für Ihre Hilfe. Auf Wiedersehen!","en":"Thanks for your help. Goodbye!","ta":"உங்கள் உதவிக்கு நன்றி. போய் வருகிறேன்!"},{"de":"Das mache ich. Vielen Dank und schönen Tag noch!","en":"I'll do that. Thanks a lot and have a nice day!","ta":"அப்படியே செய்கிறேன். மிக்க நன்றி, உங்கள் நாள் இனிதாக அமையட்டும்!"}],"tip":"To 'Gute Besserung!' (get well soon) you simply answer 'Danke!'. 'Das mache ich' = I'll do that."}],"end":"Auf Wiedersehen! Das Rezept und die Krankmeldung bekommen Sie vorne an der Anmeldung.","end_en":"Goodbye! You'll get the prescription and the sick note at the reception desk at the front.","end_ta":"போய் வாருங்கள்! மருந்துச்சீட்டையும் மருத்துவ விடுப்புச் சான்றிதழையும் முன்பக்க வரவேற்பில் பெற்றுக்கொள்ளுங்கள்.","words":[{"de":"die Beschwerden","en":"the symptoms, complaints"},{"de":"die Kopfschmerzen","en":"the headache"},{"de":"das Fieber","en":"the fever"},{"de":"Mir ist schlecht.","en":"I feel sick."},{"de":"das Rezept","en":"the prescription"},{"de":"die Krankmeldung","en":"the sick note"},{"de":"krankschreiben","en":"to sign someone off sick"},{"de":"Gute Besserung!","en":"Get well soon!"}]},
"termin":{"turns":[{"tutor":"Zahnarztpraxis Dr. Weber, Sie sprechen mit Frau Klein. Was kann ich für Sie tun?","tutor_en":"Dr Weber's dental practice, you're speaking to Ms Klein. What can I do for you?","tutor_ta":"டாக்டர் வேபர் பல் மருத்துவமனை, நீங்கள் திருமதி க்ளைனுடன் பேசுகிறீர்கள். நான் உங்களுக்கு என்ன செய்ய முடியும்?","task_en":"Say your name and that you have an appointment (use your own name).","task_ta":"உங்கள் பெயரைச் சொல்லி, உங்களுக்கு ஒரு சந்திப்பு நேரம் இருக்கிறது என்று சொல்லுங்கள் (உங்கள் சொந்தப் பெயரைப் பயன்படுத்துங்கள்).","goal":0,"options":[{"de":"Guten Tag, hier ist Kumar. Es geht um meinen Termin.","en":"Hello, this is Kumar. It's about my appointment.","ta":"வணக்கம், நான் குமார் பேசுகிறேன். என் சந்திப்பு நேரம் பற்றிப் பேச வேண்டும்."},{"de":"Guten Tag, Kumar hier. Ich habe am Donnerstag einen Termin.","en":"Hello, Kumar speaking. I have an appointment on Thursday.","ta":"வணக்கம், குமார் பேசுகிறேன். எனக்கு வியாழக்கிழமை ஒரு சந்திப்பு நேரம் இருக்கிறது."},{"de":"Hallo, mein Name ist Priya Raman. Ich habe morgen einen Termin.","en":"Hello, my name is Priya Raman. I have an appointment tomorrow.","ta":"வணக்கம், என் பெயர் பிரியா ராமன். எனக்கு நாளை ஒரு சந்திப்பு நேரம் இருக்கிறது."}],"tip":"On the phone say 'Hier ist …' or '… hier', not 'Ich bin …'. 'Es geht um …' (+ accusative) = it's about …"},{"tutor":"Ah ja, ich sehe Ihren Termin. Wie kann ich Ihnen helfen?","tutor_en":"Ah yes, I can see your appointment. How can I help you?","tutor_ta":"ஆம், உங்கள் சந்திப்பு நேரம் எனக்குத் தெரிகிறது. நான் உங்களுக்கு எப்படி உதவ முடியும்?","task_en":"Say that you can't come, and why.","task_ta":"உங்களால் வர முடியாது என்றும், ஏன் என்றும் சொல்லுங்கள்.","goal":1,"options":[{"de":"Ich kann leider nicht kommen. Ich bin krank.","en":"Unfortunately I can't come. I'm ill.","ta":"துரதிர்ஷ்டவசமாக என்னால் வர முடியாது. எனக்கு உடம்பு சரியில்லை."},{"de":"Leider kann ich nicht kommen, weil ich arbeiten muss.","en":"Unfortunately I can't come because I have to work.","ta":"எனக்கு வேலை இருப்பதால், துரதிர்ஷ்டவசமாக என்னால் வர முடியாது."},{"de":"Ich muss den Termin leider verschieben. Mein Kind ist krank.","en":"I'm afraid I have to reschedule the appointment. My child is ill.","ta":"துரதிர்ஷ்டவசமாக நான் சந்திப்பு நேரத்தை மாற்ற வேண்டும். என் குழந்தைக்கு உடம்பு சரியில்லை."}],"tip":"'weil' sends the verb to the end: …, weil ich arbeiten muss. 'einen Termin verschieben' = to reschedule an appointment."},{"tutor":"Das ist kein Problem. Möchten Sie gleich einen neuen Termin vereinbaren?","tutor_en":"That's no problem. Would you like to make a new appointment right away?","tutor_ta":"அது பிரச்சினை இல்லை. இப்போதே புதிய சந்திப்பு நேரத்தை ஏற்பாடு செய்ய விரும்புகிறீர்களா?","task_en":"Say yes and say when you have time.","task_ta":"ஆம் என்று சொல்லி, உங்களுக்கு எப்போது நேரம் இருக்கிறது என்று சொல்லுங்கள்.","goal":2,"options":[{"de":"Ja, gern. Geht es nächste Woche?","en":"Yes, please. Is next week possible?","ta":"ஆம், சரி. அடுத்த வாரம் முடியுமா?"},{"de":"Ja, bitte. Am besten nachmittags.","en":"Yes, please. Afternoons would be best.","ta":"ஆம், தயவுசெய்து. பிற்பகலில் இருந்தால் நல்லது."},{"de":"Ja. Ich habe nächste Woche vormittags Zeit.","en":"Yes. I have time next week in the mornings.","ta":"ஆம். அடுத்த வாரம் காலை நேரங்களில் எனக்கு நேரம் இருக்கிறது."}],"tip":"'Geht es …?' = is … possible? vormittags / nachmittags (with -s) = in the mornings / in the afternoons."},{"tutor":"Ich habe nächsten Dienstag um 9 Uhr oder Mittwoch um 15 Uhr. Was passt Ihnen besser?","tutor_en":"I have next Tuesday at 9 am or Wednesday at 3 pm. Which suits you better?","tutor_ta":"அடுத்த செவ்வாய்க்கிழமை காலை 9 மணி அல்லது புதன்கிழமை பிற்பகல் 3 மணி இருக்கிறது. உங்களுக்கு எது வசதியாக இருக்கும்?","task_en":"Choose one of the two appointments.","task_ta":"இரண்டு நேரங்களில் ஒன்றைத் தேர்ந்தெடுங்கள்.","goal":2,"options":[{"de":"Mittwoch um 15 Uhr, bitte.","en":"Wednesday at 3 pm, please.","ta":"புதன்கிழமை பிற்பகல் 3 மணி, தயவுசெய்து."},{"de":"Dienstag um 9 Uhr passt mir gut.","en":"Tuesday at 9 suits me well.","ta":"செவ்வாய்க்கிழமை காலை 9 மணி எனக்கு வசதியாக இருக்கும்."},{"de":"Ich nehme lieber den Termin am Mittwoch.","en":"I'd rather take the appointment on Wednesday.","ta":"நான் புதன்கிழமை சந்திப்பு நேரத்தையே எடுத்துக்கொள்கிறேன்."}],"tip":"'passen' + dative: Das passt mir. 'lieber' = rather (from 'gern'). Days take 'am': am Mittwoch."},{"tutor":"Gut, ich habe das eingetragen. Haben Sie noch eine Frage?","tutor_en":"Good, I've put it in the diary. Do you have any other questions?","tutor_ta":"சரி, நான் அதைப் பதிவு செய்துவிட்டேன். உங்களுக்கு வேறு ஏதாவது கேள்வி இருக்கிறதா?","task_en":"Ask a practical question about the appointment.","task_ta":"சந்திப்பு நேரம் பற்றி ஒரு நடைமுறைக் கேள்வி கேளுங்கள்.","goal":null,"options":[{"de":"Ja, muss ich etwas mitbringen?","en":"Yes, do I need to bring anything?","ta":"ஆம், நான் ஏதாவது கொண்டு வர வேண்டுமா?"},{"de":"Ja. Wie lange dauert der Termin?","en":"Yes. How long will the appointment take?","ta":"ஆம். சந்திப்பு எவ்வளவு நேரம் ஆகும்?"},{"de":"Ja, brauche ich meine Versichertenkarte?","en":"Yes, do I need my health insurance card?","ta":"ஆம், எனக்கு என் மருத்துவக் காப்பீட்டு அட்டை தேவையா?"}],"tip":"mitbringen is separable: Bringen Sie … mit. 'dauern' = to take (time): Wie lange dauert das?"},{"tutor":"Bringen Sie bitte Ihre Versichertenkarte mit. Der Termin dauert etwa eine halbe Stunde.","tutor_en":"Please bring your health insurance card. The appointment takes about half an hour.","tutor_ta":"தயவுசெய்து உங்கள் மருத்துவக் காப்பீட்டு அட்டையைக் கொண்டு வாருங்கள். சந்திப்பு சுமார் அரை மணி நேரம் ஆகும்.","task_en":"Confirm and thank the receptionist.","task_ta":"உறுதிசெய்து வரவேற்பாளருக்கு நன்றி சொல்லுங்கள்.","goal":2,"options":[{"de":"Alles klar. Vielen Dank!","en":"All right. Thank you very much!","ta":"சரி. மிக்க நன்றி!"},{"de":"Gut, dann bis nächste Woche. Danke!","en":"Good, see you next week then. Thanks!","ta":"சரி, அடுத்த வாரம் சந்திப்போம். நன்றி!"},{"de":"Vielen Dank und entschuldigen Sie die Umstände.","en":"Thank you very much, and sorry for the trouble.","ta":"மிக்க நன்றி, சிரமத்திற்கு மன்னிக்கவும்."}],"tip":"'bis nächste Woche' = see you next week. 'Entschuldigen Sie die Umstände' = sorry for the inconvenience."}],"end":"Gern geschehen. Bis nächste Woche, auf Wiederhören!","end_en":"You're welcome. See you next week, goodbye!","end_ta":"மகிழ்ச்சி. அடுத்த வாரம் சந்திப்போம், போய் வாருங்கள்!","words":[{"de":"der Termin","en":"the appointment"},{"de":"einen Termin verschieben","en":"to reschedule an appointment"},{"de":"einen Termin vereinbaren","en":"to make an appointment"},{"de":"absagen","en":"to cancel"},{"de":"die Zahnarztpraxis","en":"the dental practice"},{"de":"die Versichertenkarte","en":"the health insurance card"},{"de":"passen","en":"to suit"},{"de":"Auf Wiederhören!","en":"Goodbye! (on the phone)"}]},
"wohnung":{"turns":[{"tutor":"Guten Tag! Kommen Sie rein. Hier sind zwei Zimmer, Küche, Bad und ein Balkon. Wie gefällt Ihnen die Wohnung?","tutor_en":"Hello! Come in. Here are two rooms, a kitchen, a bathroom and a balcony. How do you like the flat?","tutor_ta":"வணக்கம்! உள்ளே வாருங்கள். இங்கே இரண்டு அறைகள், சமையலறை, குளியலறை, ஒரு பால்கனி இருக்கின்றன. இந்த வீடு உங்களுக்கு எப்படி இருக்கிறது?","task_en":"Say what you think of the flat.","task_ta":"இந்த வீட்டைப் பற்றி நீங்கள் என்ன நினைக்கிறீர்கள் என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Sehr schön und hell!","en":"Very nice and bright!","ta":"மிகவும் அழகாகவும் வெளிச்சமாகவும் இருக்கிறது!"},{"de":"Sie gefällt mir gut. Der Balkon ist toll.","en":"I like it. The balcony is great.","ta":"எனக்குப் பிடித்திருக்கிறது. பால்கனி அருமையாக இருக்கிறது."},{"de":"Gut, aber die Küche ist ein bisschen klein.","en":"Good, but the kitchen is a bit small.","ta":"நன்றாக இருக்கிறது, ஆனால் சமையலறை கொஞ்சம் சிறியது."}],"tip":"'gefallen' + dative: Die Wohnung gefällt mir (literally: the flat pleases me). 'ein bisschen' = a bit."},{"tutor":"Danke. Viele Leute interessieren sich für die Wohnung. Was möchten Sie wissen?","tutor_en":"Thanks. A lot of people are interested in the flat. What would you like to know?","tutor_ta":"நன்றி. பலர் இந்த வீட்டில் ஆர்வமாக இருக்கிறார்கள். நீங்கள் என்ன தெரிந்துகொள்ள விரும்புகிறீர்கள்?","task_en":"Ask about the rent and the additional costs.","task_ta":"வாடகை மற்றும் கூடுதல் செலவுகள் பற்றிக் கேளுங்கள்.","goal":0,"options":[{"de":"Wie hoch ist die Miete?","en":"How high is the rent?","ta":"வாடகை எவ்வளவு?"},{"de":"Was kostet die Wohnung mit Nebenkosten?","en":"How much is the flat including additional costs?","ta":"கூடுதல் செலவுகளுடன் சேர்த்து இந்த வீட்டுக்கு எவ்வளவு ஆகும்?"},{"de":"Wie viel kostet die Miete, und sind die Nebenkosten dabei?","en":"How much is the rent, and are the additional costs included?","ta":"வாடகை எவ்வளவு, கூடுதல் செலவுகளும் அதில் அடங்குமா?"}],"tip":"Kaltmiete = rent without extras; Nebenkosten = additional costs (water, heating, rubbish); Warmmiete = the total."},{"tutor":"Die Kaltmiete ist 750 Euro, dazu kommen 180 Euro Nebenkosten. Die Kaution beträgt drei Kaltmieten.","tutor_en":"The basic rent is 750 euros, plus 180 euros in additional costs. The deposit is three months' basic rent.","tutor_ta":"அடிப்படை வாடகை 750 யூரோ, அதனுடன் கூடுதல் செலவுகள் 180 யூரோ. முன்பணம் மூன்று மாத அடிப்படை வாடகை.","task_en":"Ask from when the flat is available.","task_ta":"வீடு எப்போதிலிருந்து காலியாக இருக்கும் என்று கேளுங்கள்.","goal":1,"options":[{"de":"Ab wann ist die Wohnung frei?","en":"From when is the flat available?","ta":"வீடு எப்போதிலிருந்து காலியாக இருக்கும்?"},{"de":"Okay. Wann kann ich einziehen?","en":"Okay. When can I move in?","ta":"சரி. நான் எப்போது குடிவரலாம்?"},{"de":"Verstehe. Ist die Wohnung ab nächsten Monat frei?","en":"I see. Is the flat available from next month?","ta":"புரிகிறது. அடுத்த மாதத்திலிருந்து வீடு காலியாக இருக்குமா?"}],"tip":"'ab' = from (a point in time): ab wann, ab nächsten Monat. einziehen (separable) = to move in."},{"tutor":"Ab dem ersten Oktober, also schon nächsten Monat. Erzählen Sie mal von sich: Was machen Sie beruflich?","tutor_en":"From the first of October, so already next month. Tell me about yourself: what do you do for a living?","tutor_ta":"அக்டோபர் 1 முதல், அதாவது அடுத்த மாதமே. உங்களைப் பற்றிச் சொல்லுங்கள்: நீங்கள் என்ன வேலை செய்கிறீர்கள்?","task_en":"Tell the landlord about your job.","task_ta":"உங்கள் வேலையைப் பற்றி வீட்டு உரிமையாளரிடம் சொல்லுங்கள்.","goal":2,"options":[{"de":"Ich arbeite als Softwareentwickler.","en":"I work as a software developer.","ta":"நான் மென்பொருள் உருவாக்குநராக வேலை செய்கிறேன்."},{"de":"Ich bin Krankenpflegerin und arbeite im Klinikum.","en":"I'm a nurse and I work at the hospital.","ta":"நான் ஒரு செவிலியர், மருத்துவமனையில் வேலை செய்கிறேன்."},{"de":"Ich habe eine feste Stelle als Ingenieur.","en":"I have a permanent job as an engineer.","ta":"எனக்குப் பொறியாளராக நிரந்தர வேலை இருக்கிறது."}],"tip":"'arbeiten als' + job, no article: Ich arbeite als Softwareentwickler. 'eine feste Stelle' (a permanent job) is important for landlords."},{"tutor":"Schön. Und wohnen Sie allein oder mit Familie?","tutor_en":"Nice. And do you live alone or with family?","tutor_ta":"நல்லது. நீங்கள் தனியாக வசிக்கிறீர்களா, அல்லது குடும்பத்துடனா?","task_en":"Say who will live in the flat with you.","task_ta":"உங்களுடன் இந்த வீட்டில் யார் வசிப்பார்கள் என்று சொல்லுங்கள்.","goal":2,"options":[{"de":"Ich wohne allein.","en":"I live alone.","ta":"நான் தனியாக வசிக்கிறேன்."},{"de":"Mit meiner Frau. Wir haben keine Kinder.","en":"With my wife. We don't have children.","ta":"என் மனைவியுடன். எங்களுக்குக் குழந்தைகள் இல்லை."},{"de":"Mit meinem Mann und unserer Tochter.","en":"With my husband and our daughter.","ta":"என் கணவர் மற்றும் எங்கள் மகளுடன்."}],"tip":"'mit' + dative: mit meiner Frau, mit meinem Mann, mit unserer Tochter."},{"tutor":"Gut. Rauchen Sie, oder haben Sie Haustiere?","tutor_en":"Good. Do you smoke, or do you have pets?","tutor_ta":"சரி. நீங்கள் புகைபிடிப்பீர்களா, அல்லது வீட்டில் செல்லப்பிராணிகள் இருக்கின்றனவா?","task_en":"Say that you don't smoke and have no pets.","task_ta":"நீங்கள் புகைபிடிப்பதில்லை, செல்லப்பிராணிகளும் இல்லை என்று சொல்லுங்கள்.","goal":null,"options":[{"de":"Nein, beides nicht.","en":"No, neither.","ta":"இல்லை, இரண்டும் இல்லை."},{"de":"Nein, ich rauche nicht und habe keine Tiere.","en":"No, I don't smoke and have no pets.","ta":"இல்லை, நான் புகைபிடிப்பதில்லை, பிராணிகளும் இல்லை."},{"de":"Nein. Ich bin Nichtraucher und habe keine Haustiere.","en":"No. I'm a non-smoker and have no pets.","ta":"இல்லை. நான் புகைபிடிக்காதவன், செல்லப்பிராணிகளும் இல்லை."}],"tip":"'nicht' negates verbs (ich rauche nicht), 'kein' negates nouns (keine Haustiere). 'beides nicht' = neither."},{"tutor":"Sehr gut. Also, was denken Sie?","tutor_en":"Very good. So, what do you think?","tutor_ta":"மிகவும் நல்லது. சரி, நீங்கள் என்ன நினைக்கிறீர்கள்?","task_en":"Say that you are interested in the flat.","task_ta":"இந்த வீட்டில் உங்களுக்கு ஆர்வம் இருக்கிறது என்று சொல்லுங்கள்.","goal":3,"options":[{"de":"Ich möchte die Wohnung gern nehmen.","en":"I'd like to take the flat.","ta":"நான் இந்த வீட்டை எடுத்துக்கொள்ள விரும்புகிறேன்."},{"de":"Ich habe großes Interesse an der Wohnung.","en":"I'm very interested in the flat.","ta":"எனக்கு இந்த வீட்டில் மிகுந்த ஆர்வம் இருக்கிறது."},{"de":"Die Wohnung gefällt mir sehr. Was brauchen Sie von mir?","en":"I really like the flat. What do you need from me?","ta":"எனக்கு இந்த வீடு மிகவும் பிடித்திருக்கிறது. உங்களுக்கு என்னிடமிருந்து என்ன தேவை?"}],"tip":"'Interesse an' + dative: Interesse an der Wohnung. Landlords usually ask for a SCHUFA report, payslips and ID."}],"end":"Das freut mich! Schicken Sie mir bitte Ihre Unterlagen: SCHUFA-Auskunft, Gehaltsnachweise und eine Kopie Ihres Ausweises.","end_en":"I'm glad! Please send me your documents: a SCHUFA credit report, payslips and a copy of your ID.","end_ta":"மகிழ்ச்சி! தயவுசெய்து உங்கள் ஆவணங்களை எனக்கு அனுப்புங்கள்: SCHUFA கடன் அறிக்கை, சம்பளச் சீட்டுகள், உங்கள் அடையாள அட்டையின் நகல்.","words":[{"de":"die Miete","en":"the rent"},{"de":"die Kaltmiete","en":"the basic rent (without extras)"},{"de":"die Nebenkosten","en":"the additional costs, utilities"},{"de":"die Kaution","en":"the deposit"},{"de":"einziehen","en":"to move in"},{"de":"der Vermieter / die Vermieterin","en":"the landlord / landlady"},{"de":"die Unterlagen","en":"the documents"},{"de":"das Haustier","en":"the pet"}]},
"apotheke":{"turns":[{"tutor":"Guten Tag! Was kann ich für Sie tun?","tutor_en":"Hello! What can I do for you?","tutor_ta":"வணக்கம்! நான் உங்களுக்கு என்ன செய்ய முடியும்?","task_en":"Describe your problem.","task_ta":"உங்கள் பிரச்சினையை விவரியுங்கள்.","goal":0,"options":[{"de":"Ich habe Husten und Schnupfen.","en":"I have a cough and a runny nose.","ta":"எனக்கு இருமலும் மூக்கு ஒழுகலும் இருக்கிறது."},{"de":"Ich brauche etwas gegen Halsschmerzen.","en":"I need something for a sore throat.","ta":"எனக்குத் தொண்டை வலிக்கு ஏதாவது வேண்டும்."},{"de":"Ich bin erkältet und kann nachts nicht gut schlafen.","en":"I have a cold and can't sleep well at night.","ta":"எனக்குச் சளி பிடித்திருக்கிறது, இரவில் சரியாகத் தூங்க முடியவில்லை."}],"tip":"'etwas gegen …' = something for … (literally 'against'). 'erkältet sein' = to have a cold."},{"tutor":"Seit wann haben Sie das? Haben Sie auch Fieber?","tutor_en":"How long have you had it? Do you also have a fever?","tutor_ta":"இது எப்போதிலிருந்து இருக்கிறது? உங்களுக்குக் காய்ச்சலும் இருக்கிறதா?","task_en":"Say since when, and that you have no fever.","task_ta":"எப்போதிலிருந்து என்றும், காய்ச்சல் இல்லை என்றும் சொல்லுங்கள்.","goal":0,"options":[{"de":"Seit zwei Tagen. Kein Fieber.","en":"For two days. No fever.","ta":"இரண்டு நாட்களாக. காய்ச்சல் இல்லை."},{"de":"Seit gestern, aber ich habe kein Fieber.","en":"Since yesterday, but I have no fever.","ta":"நேற்றிலிருந்து, ஆனால் எனக்குக் காய்ச்சல் இல்லை."},{"de":"Seit ein paar Tagen. Fieber habe ich nicht.","en":"For a few days. I don't have a fever.","ta":"சில நாட்களாக. எனக்குக் காய்ச்சல் இல்லை."}],"tip":"Use 'kein' before nouns: kein Fieber. 'seit ein paar Tagen' = for a few days ('ein paar' never changes)."},{"tutor":"Dann empfehle ich Ihnen dieses Mittel. Es hilft gut bei Erkältungen.","tutor_en":"Then I recommend this remedy. It works well for colds.","tutor_ta":"அப்படியானால் இந்த மருந்தைப் பரிந்துரைக்கிறேன். இது சளிக்கு நன்றாக உதவும்.","task_en":"Ask how often you should take it.","task_ta":"இதை எத்தனை முறை எடுத்துக்கொள்ள வேண்டும் என்று கேளுங்கள்.","goal":1,"options":[{"de":"Wie oft soll ich das nehmen?","en":"How often should I take it?","ta":"நான் இதை எத்தனை முறை எடுத்துக்கொள்ள வேண்டும்?"},{"de":"Danke. Wie nehme ich das Mittel ein?","en":"Thanks. How do I take the medicine?","ta":"நன்றி. இந்த மருந்தை எப்படி எடுத்துக்கொள்வது?"},{"de":"Wie oft am Tag und wie lange soll ich es nehmen?","en":"How many times a day and for how long should I take it?","ta":"ஒரு நாளைக்கு எத்தனை முறை, எத்தனை நாட்கள் இதை எடுத்துக்கொள்ள வேண்டும்?"}],"tip":"einnehmen (separable) = to take medicine: Ich nehme das Mittel ein. 'Wie oft?' = how often?"},{"tutor":"Dreimal täglich eine Tablette, nach dem Essen. Höchstens eine Woche lang.","tutor_en":"One tablet three times a day, after meals. For one week at most.","tutor_ta":"ஒரு நாளைக்கு மூன்று முறை ஒரு மாத்திரை, சாப்பிட்ட பிறகு. அதிகபட்சம் ஒரு வாரம்.","task_en":"Check that you understood, or ask about side effects.","task_ta":"நீங்கள் சரியாகப் புரிந்துகொண்டீர்களா என்று சரிபாருங்கள், அல்லது பக்க விளைவுகள் பற்றிக் கேளுங்கள்.","goal":1,"options":[{"de":"Also dreimal am Tag, nach dem Essen?","en":"So three times a day, after meals?","ta":"அப்படியானால் ஒரு நாளைக்கு மூன்று முறை, சாப்பிட்ட பிறகா?"},{"de":"Verstanden. Gibt es Nebenwirkungen?","en":"Understood. Are there any side effects?","ta":"புரிந்தது. பக்க விளைவுகள் ஏதாவது இருக்கிறதா?"},{"de":"Nach dem Essen, okay. Macht das Mittel müde?","en":"After meals, okay. Does the medicine make you tired?","ta":"சாப்பிட்ட பிறகு, சரி. இந்த மருந்து தூக்கக் கலக்கத்தை ஏற்படுத்துமா?"}],"tip":"'Also …?' repeats the key facts to check. 'dreimal täglich' = 'dreimal am Tag' = three times a day."},{"tutor":"Ja. Es kann ein bisschen müde machen. Fahren Sie dann bitte nicht Auto.","tutor_en":"Yes. It can make you a bit tired. So please don't drive.","tutor_ta":"ஆம். இது கொஞ்சம் தூக்கக் கலக்கத்தை ஏற்படுத்தலாம். அதனால் தயவுசெய்து வாகனம் ஓட்ட வேண்டாம்.","task_en":"Say OK and ask about the price.","task_ta":"சரி என்று சொல்லி, விலையைப் பற்றிக் கேளுங்கள்.","goal":2,"options":[{"de":"Okay. Was kostet das?","en":"Okay. How much is it?","ta":"சரி. இது எவ்வளவு?"},{"de":"Gut zu wissen. Wie viel kostet das Mittel?","en":"Good to know. How much does the medicine cost?","ta":"தெரிந்துகொண்டது நல்லது. இந்த மருந்தின் விலை எவ்வளவு?"},{"de":"Alles klar. Gibt es auch eine günstigere Packung?","en":"All right. Is there a cheaper pack too?","ta":"சரி. விலை குறைவான பாக்கெட்டும் இருக்கிறதா?"}],"tip":"'günstig' = good value, cheap → 'günstiger' = cheaper. 'Wie viel kostet …?' asks the price."},{"tutor":"Die große Packung kostet 8,95 Euro, die kleine 5,49 Euro. Welche möchten Sie?","tutor_en":"The big pack costs 8.95 euros, the small one 5.49 euros. Which one would you like?","tutor_ta":"பெரிய பாக்கெட் 8.95 யூரோ, சிறியது 5.49 யூரோ. உங்களுக்கு எது வேண்டும்?","task_en":"Choose a pack.","task_ta":"ஒரு பாக்கெட்டைத் தேர்ந்தெடுங்கள்.","goal":null,"options":[{"de":"Die kleine, bitte.","en":"The small one, please.","ta":"சிறியது, தயவுசெய்து."},{"de":"Ich nehme die große Packung.","en":"I'll take the big pack.","ta":"நான் பெரிய பாக்கெட்டை எடுத்துக்கொள்கிறேன்."},{"de":"Die kleine reicht, glaube ich. Danke!","en":"The small one is enough, I think. Thanks!","ta":"சிறியதே போதும் என்று நினைக்கிறேன். நன்றி!"}],"tip":"An adjective can stand without its noun: die kleine (Packung), die große (Packung). 'reichen' = to be enough."},{"tutor":"Gern. Brauchen Sie sonst noch etwas?","tutor_en":"Certainly. Do you need anything else?","tutor_ta":"சரி. உங்களுக்கு வேறு ஏதாவது தேவையா?","task_en":"Say no, thank the pharmacist and say goodbye.","task_ta":"இல்லை என்று சொல்லி, மருந்தாளருக்கு நன்றி சொல்லி விடைபெறுங்கள்.","goal":null,"options":[{"de":"Nein, danke. Tschüss!","en":"No, thanks. Bye!","ta":"இல்லை, நன்றி. பை!"},{"de":"Nein, das ist alles. Vielen Dank!","en":"No, that's all. Thank you very much!","ta":"இல்லை, அவ்வளவுதான். மிக்க நன்றி!"},{"de":"Nein, danke. Sie haben mir sehr geholfen.","en":"No, thanks. You've been a great help.","ta":"இல்லை, நன்றி. நீங்கள் எனக்கு மிகவும் உதவினீர்கள்."}],"tip":"'helfen' takes the dative: Sie haben mir geholfen (Perfekt of helfen = hat geholfen)."}],"end":"Gern geschehen. Gute Besserung und auf Wiedersehen!","end_en":"You're welcome. Get well soon, and goodbye!","end_ta":"மகிழ்ச்சி. விரைவில் குணமடையுங்கள், போய் வாருங்கள்!","words":[{"de":"die Apotheke","en":"the pharmacy"},{"de":"das Mittel","en":"the remedy, medicine"},{"de":"die Tablette","en":"the tablet"},{"de":"der Husten","en":"the cough"},{"de":"der Schnupfen","en":"the runny nose, head cold"},{"de":"einnehmen","en":"to take (medicine)"},{"de":"die Nebenwirkung","en":"the side effect"},{"de":"dreimal täglich","en":"three times a day"}]},
"kollegen":{"turns":[{"tutor":"Guten Morgen! Na, wie geht's dir heute?","tutor_en":"Good morning! So, how are you today?","tutor_ta":"காலை வணக்கம்! இன்று எப்படி இருக்கிறாய்?","task_en":"Greet back and say how you are","task_ta":"பதிலுக்கு வணக்கம் சொல்லி, நீங்கள் எப்படி இருக்கிறீர்கள் என்று சொல்லுங்கள்","goal":null,"options":[{"de":"Guten Morgen! Gut, danke.","en":"Good morning! Fine, thanks.","ta":"காலை வணக்கம்! நன்றாக இருக்கிறேன், நன்றி."},{"de":"Morgen! Mir geht's ganz gut.","en":"Morning! I'm doing quite well.","ta":"காலை வணக்கம்! நான் நன்றாகவே இருக்கிறேன்."},{"de":"Guten Morgen! Sehr gut, danke.","en":"Good morning! Very well, thanks.","ta":"காலை வணக்கம்! மிகவும் நன்றாக இருக்கிறேன், நன்றி."}],"tip":"'Morgen!' is the casual short form of 'Guten Morgen!'. Mir geht's = mir geht es (Dativ: mir)."},{"tutor":"Freut mich! Nimm dir einen Kaffee, er ist frisch. Wie war dein Wochenende?","tutor_en":"Glad to hear it! Have a coffee, it's fresh. How was your weekend?","tutor_ta":"மகிழ்ச்சி! ஒரு காபி எடுத்துக்கொள், இப்போதுதான் போட்டது. உன் வார இறுதி எப்படி இருந்தது?","task_en":"Say how your weekend was and one thing you did","task_ta":"உங்கள் வார இறுதி எப்படி இருந்தது, நீங்கள் செய்த ஒரு விஷயம் என்ன என்று சொல்லுங்கள்","goal":0,"options":[{"de":"Es war schön. Ich war im Park.","en":"It was nice. I was in the park.","ta":"நன்றாக இருந்தது. நான் பூங்காவில் இருந்தேன்."},{"de":"Sehr gut! Ich habe Freunde getroffen.","en":"Very good! I met friends.","ta":"மிகவும் நன்றாக இருந்தது! நான் நண்பர்களைச் சந்தித்தேன்."},{"de":"Ganz entspannt. Ich habe lange geschlafen und gekocht.","en":"Very relaxed. I slept in and cooked.","ta":"மிகவும் நிம்மதியாக இருந்தது. நான் நீண்ட நேரம் தூங்கினேன், சமைத்தேன்."}],"tip":"war = was (past of sein). Perfekt: haben + participle at the end: Ich habe Freunde getroffen."},{"tutor":"Klingt gut! Und was hast du am Sonntag gemacht?","tutor_en":"Sounds good! And what did you do on Sunday?","tutor_ta":"நன்றாக இருக்கிறதே! ஞாயிற்றுக்கிழமை நீ என்ன செய்தாய்?","task_en":"Say what you did on Sunday","task_ta":"ஞாயிற்றுக்கிழமை நீங்கள் என்ன செய்தீர்கள் என்று சொல்லுங்கள்","goal":0,"options":[{"de":"Ich habe meine Familie angerufen.","en":"I called my family.","ta":"நான் என் குடும்பத்தினருக்கு ஃபோன் செய்தேன்."},{"de":"Am Sonntag bin ich Fahrrad gefahren.","en":"On Sunday I went cycling.","ta":"ஞாயிற்றுக்கிழமை நான் சைக்கிள் ஓட்டினேன்."},{"de":"Ich habe Sambar und Reis für Freunde gekocht.","en":"I cooked sambar and rice for friends.","ta":"நண்பர்களுக்காக சாம்பாரும் சாதமும் சமைத்தேன்."}],"tip":"Verbs of movement like fahren take sein: Ich bin gefahren. Time first, verb second: Am Sonntag bin ich ..."},{"tutor":"Das klingt nach einem schönen Wochenende!","tutor_en":"That sounds like a nice weekend!","tutor_ta":"அது ஒரு நல்ல வார இறுதி போலத் தெரிகிறது!","task_en":"Ask your colleague about their weekend","task_ta":"உங்கள் சக ஊழியரிடம் அவருடைய வார இறுதி பற்றிக் கேளுங்கள்","goal":1,"options":[{"de":"Und du? Wie war dein Wochenende?","en":"And you? How was your weekend?","ta":"நீ? உன் வார இறுதி எப்படி இருந்தது?"},{"de":"Was hast du am Wochenende gemacht?","en":"What did you do at the weekend?","ta":"வார இறுதியில் நீ என்ன செய்தாய்?"},{"de":"Und wie war dein Wochenende? Warst du unterwegs?","en":"And how was your weekend? Were you away?","ta":"உன் வார இறுதி எப்படி இருந்தது? எங்காவது வெளியே போயிருந்தாயா?"}],"tip":"Use du with colleagues who say du to you. am Wochenende = at the weekend; unterwegs sein = to be out and about."},{"tutor":"Ich war mit meiner Frau in Hamburg. Wir haben eine Hafenrundfahrt gemacht. Warst du schon mal in Hamburg?","tutor_en":"I was in Hamburg with my wife. We did a harbour boat tour. Have you ever been to Hamburg?","tutor_ta":"நான் என் மனைவியுடன் ஹாம்பர்க் போயிருந்தேன். நாங்கள் துறைமுகத்தில் படகுச் சுற்றுலா போனோம். நீ எப்போதாவது ஹாம்பர்க் போயிருக்கிறாயா?","task_en":"Answer and react to what your colleague told you","task_ta":"பதில் சொல்லி, சக ஊழியர் சொன்னதற்கு உங்கள் எதிர்வினையைத் தெரிவியுங்கள்","goal":null,"options":[{"de":"Nein, noch nie. Das klingt toll!","en":"No, never. That sounds great!","ta":"இல்லை, ஒருபோதும் போனதில்லை. அது அருமையாக இருக்கிறது!"},{"de":"Nein, noch nicht, aber ich möchte gern hinfahren.","en":"No, not yet, but I'd like to go there.","ta":"இல்லை, இன்னும் போகவில்லை, ஆனால் போக ஆசையாக இருக்கிறது."},{"de":"Ja, einmal. Die Stadt ist wunderschön!","en":"Yes, once. The city is beautiful!","ta":"ஆம், ஒரு முறை போயிருக்கிறேன். அந்த நகரம் மிக அழகானது!"}],"tip":"noch nie = never (so far); noch nicht = not yet. hinfahren = to go there (by transport)."},{"tutor":"Hamburg lohnt sich wirklich. Sag mal, hast du heute Mittag schon was vor?","tutor_en":"Hamburg is really worth it. Tell me, do you have any plans for lunch today?","tutor_ta":"ஹாம்பர்க் உண்மையிலேயே போக வேண்டிய இடம். சொல்லு, இன்று மதியம் ஏதாவது திட்டம் இருக்கிறதா?","task_en":"Suggest having lunch together","task_ta":"மதிய உணவைச் சேர்ந்து சாப்பிடலாம் என்று பரிந்துரையுங்கள்","goal":2,"options":[{"de":"Nein. Wollen wir zusammen essen gehen?","en":"No. Shall we go and eat together?","ta":"இல்லை. நாம் சேர்ந்து சாப்பிடப் போகலாமா?"},{"de":"Noch nicht. Gehen wir zusammen in die Kantine?","en":"Not yet. Shall we go to the canteen together?","ta":"இன்னும் இல்லை. நாம் சேர்ந்து கேன்டீனுக்குப் போகலாமா?"},{"de":"Nein. Wie wäre es mit dem Italiener um die Ecke?","en":"No. How about the Italian place around the corner?","ta":"இல்லை. பக்கத்தில் உள்ள இத்தாலிய உணவகத்துக்குப் போனால் எப்படி?"}],"tip":"Suggestions: Wollen wir ...? / Gehen wir ...? / Wie wäre es mit + Dativ (mit dem Italiener). etwas vorhaben = to have plans."},{"tutor":"Gute Idee! Wann passt es dir?","tutor_en":"Good idea! When suits you?","tutor_ta":"நல்ல யோசனை! உனக்கு எப்போது வசதி?","task_en":"Suggest a time","task_ta":"ஒரு நேரத்தைப் பரிந்துரையுங்கள்","goal":2,"options":[{"de":"Um zwölf Uhr?","en":"At twelve o'clock?","ta":"பன்னிரண்டு மணிக்கு?"},{"de":"Passt dir halb eins?","en":"Does half past twelve suit you?","ta":"பன்னிரண்டரை மணி உனக்கு வசதியா?"},{"de":"Um zwölf. Ich hole dich an deinem Platz ab.","en":"At twelve. I'll pick you up at your desk.","ta":"பன்னிரண்டு மணிக்கு. நான் உன் இடத்துக்கு வந்து உன்னைக் கூட்டிக்கொண்டு போகிறேன்."}],"tip":"halb eins = 12:30 (half way to one). passen + Dativ: Passt dir ...? abholen is separable: Ich hole dich ab."}],"end":"Perfekt, das passt! Dann bis später – jetzt erst mal an die Arbeit.","end_en":"Perfect, that works! See you later then – but now, back to work.","end_ta":"சரி, அது வசதிதான்! அப்புறம் பார்க்கலாம் – இப்போது முதலில் வேலையைப் பார்ப்போம்.","words":[{"de":"das Wochenende","en":"the weekend"},{"de":"die Mittagspause","en":"the lunch break"},{"de":"die Kantine","en":"the canteen"},{"de":"etwas vorhaben","en":"to have plans"},{"de":"unterwegs sein","en":"to be out and about"},{"de":"Wollen wir …?","en":"Shall we …?"},{"de":"Wie wäre es mit …?","en":"How about …?"},{"de":"abholen","en":"to pick up"}]},
"amt":{"turns":[{"tutor":"Guten Tag, nehmen Sie bitte Platz. Was kann ich für Sie tun?","tutor_en":"Hello, please take a seat. What can I do for you?","tutor_ta":"வணக்கம், தயவுசெய்து உட்காருங்கள். நான் உங்களுக்கு என்ன உதவி செய்யலாம்?","task_en":"Say why you are here","task_ta":"நீங்கள் ஏன் வந்திருக்கிறீர்கள் என்று சொல்லுங்கள்","goal":0,"options":[{"de":"Guten Tag, ich möchte mich anmelden.","en":"Hello, I'd like to register my address.","ta":"வணக்கம், நான் என் முகவரியைப் பதிவு செய்ய விரும்புகிறேன்."},{"de":"Ich bin umgezogen und möchte meine neue Wohnung anmelden.","en":"I've moved and would like to register my new flat.","ta":"நான் வீடு மாறியிருக்கிறேன், என் புதிய வீட்டைப் பதிவு செய்ய விரும்புகிறேன்."},{"de":"Ich bin neu in Berlin und möchte meinen Wohnsitz anmelden.","en":"I'm new in Berlin and would like to register my residence.","ta":"நான் பெர்லினுக்குப் புதியவன்/புதியவள், என் வசிப்பிடத்தைப் பதிவு செய்ய விரும்புகிறேன்."}],"tip":"sich anmelden = to register (reflexive). umziehen takes sein in the Perfekt: Ich bin umgezogen."},{"tutor":"Gut. Wie lautet Ihre neue Adresse?","tutor_en":"Good. What is your new address?","tutor_ta":"சரி. உங்கள் புதிய முகவரி என்ன?","task_en":"Give your new address","task_ta":"உங்கள் புதிய முகவரியைச் சொல்லுங்கள்","goal":1,"options":[{"de":"Lindenstraße 12 in Berlin-Mitte.","en":"Lindenstraße 12 in Berlin-Mitte.","ta":"பெர்லின்-மிட்டேயில் லிண்டன்ஷ்ட்ராஸே 12."},{"de":"Ich wohne jetzt in der Lindenstraße 12.","en":"I now live at Lindenstraße 12.","ta":"நான் இப்போது லிண்டன்ஷ்ட்ராஸே 12-இல் வசிக்கிறேன்."},{"de":"Meine neue Adresse ist Lindenstraße 12, zweiter Stock.","en":"My new address is Lindenstraße 12, second floor.","ta":"என் புதிய முகவரி லிண்டன்ஷ்ட்ராஸே 12, இரண்டாவது மாடி."}],"tip":"wohnen in der ...straße (Dativ). In German addresses the house number comes after the street name."},{"tutor":"Und seit wann wohnen Sie dort?","tutor_en":"And since when have you been living there?","tutor_ta":"நீங்கள் அங்கே எப்போதிலிருந்து வசிக்கிறீர்கள்?","task_en":"Say when you moved in","task_ta":"நீங்கள் எப்போது குடிவந்தீர்கள் என்று சொல்லுங்கள்","goal":1,"options":[{"de":"Seit dem ersten September.","en":"Since the first of September.","ta":"செப்டம்பர் ஒன்றாம் தேதியிலிருந்து."},{"de":"Ich bin vor zwei Wochen eingezogen.","en":"I moved in two weeks ago.","ta":"நான் இரண்டு வாரங்களுக்கு முன்பு குடிவந்தேன்."},{"de":"Seit Anfang des Monats, also seit etwa zehn Tagen.","en":"Since the beginning of the month, so for about ten days.","ta":"இந்த மாதத் தொடக்கத்திலிருந்து, அதாவது சுமார் பத்து நாட்களாக."}],"tip":"seit + Dativ with the present tense: Ich wohne seit ... ; vor + Dativ = ago. You must register within two weeks of moving in."},{"tutor":"Sind Sie verheiratet? Und wohnen noch andere Personen in der Wohnung?","tutor_en":"Are you married? And do any other people live in the flat?","tutor_ta":"உங்களுக்குத் திருமணமாகிவிட்டதா? அந்த வீட்டில் வேறு யாராவது வசிக்கிறார்களா?","task_en":"Answer the questions about your family","task_ta":"உங்கள் குடும்பம் பற்றிய கேள்விகளுக்குப் பதில் சொல்லுங்கள்","goal":1,"options":[{"de":"Nein, ich bin ledig und wohne allein.","en":"No, I'm single and live alone.","ta":"இல்லை, எனக்குத் திருமணமாகவில்லை, நான் தனியாக வசிக்கிறேன்."},{"de":"Ja, ich bin verheiratet. Meine Frau kommt nächsten Monat.","en":"Yes, I'm married. My wife is coming next month.","ta":"ஆம், எனக்குத் திருமணமாகிவிட்டது. என் மனைவி அடுத்த மாதம் வருகிறார்."},{"de":"Ja, ich wohne dort mit meinem Mann und unserer Tochter.","en":"Yes, I live there with my husband and our daughter.","ta":"ஆம், நான் அங்கே என் கணவருடனும் எங்கள் மகளுடனும் வசிக்கிறேன்."}],"tip":"ledig = single (the official word on forms). mit + Dativ: mit meinem Mann, mit unserer Tochter."},{"tutor":"Gut, das habe ich notiert. Jetzt brauche ich Ihren Pass und die Wohnungsgeberbestätigung.","tutor_en":"Fine, I've noted that. Now I need your passport and the landlord's confirmation.","tutor_ta":"சரி, அதைக் குறித்துக்கொண்டேன். இப்போது எனக்கு உங்கள் பாஸ்போர்ட்டும் வீட்டு உரிமையாளரின் உறுதிப்படிவமும் தேவை.","task_en":"Hand over your papers and ask if any documents are missing","task_ta":"உங்கள் ஆவணங்களைக் கொடுத்து, இன்னும் ஏதாவது ஆவணம் குறைகிறதா என்று கேளுங்கள்","goal":2,"options":[{"de":"Bitte schön. Fehlt noch etwas?","en":"Here you are. Is anything else missing?","ta":"இதோ. இன்னும் ஏதாவது குறைகிறதா?"},{"de":"Hier, bitte. Welche Unterlagen fehlen noch?","en":"Here you are. Which documents are still missing?","ta":"இதோ. இன்னும் எந்த ஆவணங்கள் குறைகின்றன?"},{"de":"Hier sind mein Pass und die Bestätigung. Brauchen Sie noch etwas?","en":"Here are my passport and the confirmation. Do you need anything else?","ta":"இதோ என் பாஸ்போர்ட்டும் உறுதிப்படிவமும். உங்களுக்கு இன்னும் ஏதாவது தேவையா?"}],"tip":"fehlen = to be missing: Was fehlt noch? die Unterlagen (plural only) = documents, papers."},{"tutor":"Nein, es fehlt nichts, alles ist vollständig. Einen Moment, ich gebe Ihre Daten ein … So, fertig! Haben Sie noch eine Frage?","tutor_en":"No, nothing is missing, everything is complete. One moment, I'll enter your details … There, done! Do you have any other questions?","tutor_ta":"இல்லை, எதுவும் குறையவில்லை, எல்லாம் முழுமையாக இருக்கிறது. ஒரு நிமிடம், உங்கள் விவரங்களை உள்ளிடுகிறேன் … சரி, முடிந்தது! உங்களுக்கு வேறு ஏதாவது கேள்வி இருக்கிறதா?","task_en":"Ask about the registration certificate","task_ta":"பதிவுச் சான்றிதழ் (Meldebescheinigung) பற்றிக் கேளுங்கள்","goal":3,"options":[{"de":"Bekomme ich eine Meldebescheinigung?","en":"Do I get a registration certificate?","ta":"எனக்குப் பதிவுச் சான்றிதழ் கிடைக்குமா?"},{"de":"Ja, wann bekomme ich die Meldebescheinigung?","en":"Yes, when do I get the registration certificate?","ta":"ஆம், பதிவுச் சான்றிதழ் எனக்கு எப்போது கிடைக்கும்?"},{"de":"Könnten Sie mir bitte gleich eine Meldebescheinigung ausdrucken?","en":"Could you please print me a registration certificate right away?","ta":"தயவுசெய்து இப்போதே எனக்கு ஒரு பதிவுச் சான்றிதழை அச்சிட்டுத் தர முடியுமா?"}],"tip":"Könnten Sie ...? (Konjunktiv II) is a very polite request; the infinitive (ausdrucken) goes to the end."},{"tutor":"Ja, natürlich, die drucke ich Ihnen sofort aus. Wofür brauchen Sie sie denn?","tutor_en":"Yes, of course, I'll print it for you right away. What do you need it for?","tutor_ta":"ஆம், நிச்சயமாக, அதை உடனே அச்சிட்டுத் தருகிறேன். அது உங்களுக்கு எதற்காகத் தேவை?","task_en":"Say what you need the certificate for","task_ta":"சான்றிதழ் உங்களுக்கு எதற்காகத் தேவை என்று சொல்லுங்கள்","goal":3,"options":[{"de":"Für mein Bankkonto.","en":"For my bank account.","ta":"என் வங்கிக் கணக்குக்காக."},{"de":"Für meinen Arbeitgeber und die Krankenkasse.","en":"For my employer and the health insurance.","ta":"என் பணியளிப்பவருக்கும் சுகாதாரக் காப்பீட்டு நிறுவனத்துக்கும்."},{"de":"Ich brauche sie, um ein Konto zu eröffnen.","en":"I need it to open an account.","ta":"ஒரு வங்கிக் கணக்கைத் தொடங்க எனக்கு அது தேவை."}],"tip":"für + Akkusativ: für meinen Arbeitgeber. um ... zu + infinitive = in order to: um ein Konto zu eröffnen."}],"end":"Hier ist Ihre Meldebescheinigung. Ihre Steuer-ID bekommen Sie in ein paar Wochen per Post. Auf Wiedersehen!","end_en":"Here is your registration certificate. You'll get your tax ID by post in a few weeks. Goodbye!","end_ta":"இதோ உங்கள் பதிவுச் சான்றிதழ். உங்கள் வரி அடையாள எண் சில வாரங்களில் தபாலில் வரும். போய் வாருங்கள்!","words":[{"de":"die Anmeldung","en":"the registration"},{"de":"die Meldebescheinigung","en":"the registration certificate"},{"de":"die Wohnungsgeberbestätigung","en":"the landlord's confirmation of move-in"},{"de":"der Reisepass","en":"the passport"},{"de":"die Unterlagen (Pl.)","en":"the documents"},{"de":"ledig","en":"single (not married)"},{"de":"umziehen","en":"to move (house)"},{"de":"fehlen","en":"to be missing"}]},
"bank":{"turns":[{"tutor":"Guten Tag! Was kann ich für Sie tun?","tutor_en":"Hello! What can I do for you?","tutor_ta":"வணக்கம்! நான் உங்களுக்கு என்ன உதவி செய்யலாம்?","task_en":"Say that you want to open an account","task_ta":"நீங்கள் ஒரு வங்கிக் கணக்கைத் தொடங்க விரும்புவதாகச் சொல்லுங்கள்","goal":0,"options":[{"de":"Ich möchte ein Girokonto eröffnen.","en":"I'd like to open a current account.","ta":"நான் ஒரு நடப்புக் கணக்கைத் தொடங்க விரும்புகிறேன்."},{"de":"Guten Tag, ich brauche ein Konto für mein Gehalt.","en":"Hello, I need an account for my salary.","ta":"வணக்கம், என் சம்பளத்துக்காக எனக்கு ஒரு கணக்கு தேவை."},{"de":"Ich würde gern ein Konto eröffnen, weil ich hier arbeite.","en":"I'd like to open an account because I work here.","ta":"நான் இங்கே வேலை செய்வதால் ஒரு கணக்கைத் தொடங்க விரும்புகிறேன்."}],"tip":"das Girokonto = current (everyday) account. ein Konto eröffnen = to open an account. weil sends the verb to the end."},{"tutor":"Gern. Sind Sie schon Kunde bei uns, oder ist das Ihr erstes Konto in Deutschland?","tutor_en":"Gladly. Are you already a customer with us, or is this your first account in Germany?","tutor_ta":"சரி. நீங்கள் ஏற்கனவே எங்கள் வாடிக்கையாளரா, அல்லது இது ஜெர்மனியில் உங்கள் முதல் கணக்கா?","task_en":"Say that this is your first account here","task_ta":"இது இங்கே உங்கள் முதல் கணக்கு என்று சொல்லுங்கள்","goal":null,"options":[{"de":"Das ist mein erstes Konto hier.","en":"This is my first account here.","ta":"இது இங்கே என் முதல் கணக்கு."},{"de":"Ich bin neu in Deutschland. Es ist mein erstes Konto.","en":"I'm new in Germany. It's my first account.","ta":"நான் ஜெர்மனிக்குப் புதியவன்/புதியவள். இது என் முதல் கணக்கு."},{"de":"Ich bin noch kein Kunde. Ich komme aus Chennai.","en":"I'm not a customer yet. I come from Chennai.","ta":"நான் இன்னும் வாடிக்கையாளர் இல்லை. நான் சென்னையிலிருந்து வருகிறேன்."}],"tip":"noch kein + noun = not yet a ...: Ich bin noch kein Kunde. mein erstes Konto (das Konto → erstes)."},{"tutor":"Herzlich willkommen! Wir haben ein Online-Konto und ein Konto für Berufstätige mit Service in der Filiale. Welches interessiert Sie?","tutor_en":"Welcome! We have an online account and an account for working people with service in the branch. Which one interests you?","tutor_ta":"அன்புடன் வரவேற்கிறோம்! எங்களிடம் ஒரு ஆன்லைன் கணக்கும், கிளையில் சேவையுடன் கூடிய பணியாளர்களுக்கான கணக்கும் உள்ளன. உங்களுக்கு எது விருப்பம்?","task_en":"Choose which account you want","task_ta":"உங்களுக்கு எந்தக் கணக்கு வேண்டும் என்று தேர்ந்தெடுங்கள்","goal":0,"options":[{"de":"Das Online-Konto, bitte.","en":"The online account, please.","ta":"ஆன்லைன் கணக்கு, தயவுசெய்து."},{"de":"Mich interessiert das Konto mit Service in der Filiale.","en":"I'm interested in the account with service in the branch.","ta":"கிளையில் சேவையுடன் கூடிய கணக்கில் எனக்கு ஆர்வம் இருக்கிறது."},{"de":"Ich glaube, das Online-Konto passt besser zu mir.","en":"I think the online account suits me better.","ta":"ஆன்லைன் கணக்குதான் எனக்குப் பொருத்தமானது என்று நினைக்கிறேன்."}],"tip":"etwas interessiert mich = I'm interested in something. passen zu + Dativ: passt zu mir = suits me."},{"tutor":"Eine gute Wahl. Haben Sie Fragen dazu?","tutor_en":"A good choice. Do you have any questions about it?","tutor_ta":"நல்ல தேர்வு. அதைப் பற்றி உங்களுக்கு ஏதாவது கேள்விகள் உள்ளனவா?","task_en":"Ask about the fees","task_ta":"கட்டணங்கள் பற்றிக் கேளுங்கள்","goal":1,"options":[{"de":"Was kostet das Konto im Monat?","en":"How much does the account cost per month?","ta":"இந்தக் கணக்குக்கு மாதம் எவ்வளவு கட்டணம்?"},{"de":"Gibt es Kontoführungsgebühren?","en":"Are there account fees?","ta":"கணக்குப் பராமரிப்புக் கட்டணங்கள் உள்ளனவா?"},{"de":"Wie hoch sind die Gebühren, zum Beispiel beim Geldabheben?","en":"How high are the fees, for example for withdrawing cash?","ta":"கட்டணங்கள் எவ்வளவு, உதாரணமாகப் பணம் எடுக்கும்போது?"}],"tip":"die Kontoführungsgebühren = account maintenance fees. Wie hoch sind ...? = How high/much are ...? beim = bei dem."},{"tutor":"Das Online-Konto ist kostenlos, das Konto mit Filialservice kostet 4,90 Euro im Monat. Geldabheben an unseren Automaten ist immer gratis. Möchten Sie das Konto heute eröffnen?","tutor_en":"The online account is free, the account with branch service costs 4.90 euros a month. Withdrawing cash at our machines is always free. Would you like to open the account today?","tutor_ta":"ஆன்லைன் கணக்கு இலவசம், கிளைச் சேவையுடன் கூடிய கணக்குக்கு மாதம் 4.90 யூரோ. எங்கள் ஏடிஎம்களில் பணம் எடுப்பது எப்போதும் இலவசம். இன்றே கணக்கைத் தொடங்க விரும்புகிறீர்களா?","task_en":"Say yes and ask about the bank card","task_ta":"ஆம் என்று சொல்லி, வங்கி அட்டை பற்றிக் கேளுங்கள்","goal":2,"options":[{"de":"Ja, gern. Bekomme ich auch eine Bankkarte?","en":"Yes, please. Do I also get a bank card?","ta":"ஆம், நிச்சயமாக. எனக்கு வங்கி அட்டையும் கிடைக்குமா?"},{"de":"Ja. Wann bekomme ich meine Karte?","en":"Yes. When do I get my card?","ta":"ஆம். என் அட்டை எனக்கு எப்போது கிடைக்கும்?"},{"de":"Ja, bitte. Kann ich mit der Karte kontaktlos bezahlen?","en":"Yes, please. Can I pay contactless with the card?","ta":"ஆம், தயவுசெய்து. அந்த அட்டையைக் கொண்டு தொடாமல் (contactless) பணம் செலுத்த முடியுமா?"}],"tip":"In Germany the debit card is often called Girocard or EC-Karte. mit der Karte (Dativ) = with the card."},{"tutor":"Ja, natürlich. Die Karte kommt in etwa einer Woche per Post, die PIN kommt separat. Was möchten Sie noch wissen?","tutor_en":"Yes, of course. The card arrives by post in about a week, the PIN comes separately. What else would you like to know?","tutor_ta":"ஆம், நிச்சயமாக. அட்டை சுமார் ஒரு வாரத்தில் தபாலில் வரும், PIN தனியாக வரும். வேறு என்ன தெரிந்துகொள்ள விரும்புகிறீர்கள்?","task_en":"Ask about online banking","task_ta":"ஆன்லைன் பேங்கிங் பற்றிக் கேளுங்கள்","goal":2,"options":[{"de":"Wie funktioniert das Online-Banking?","en":"How does online banking work?","ta":"ஆன்லைன் பேங்கிங் எப்படிச் செயல்படுகிறது?"},{"de":"Gibt es eine App für das Online-Banking?","en":"Is there an app for online banking?","ta":"ஆன்லைன் பேங்கிங்குக்கு ஒரு ஆப் இருக்கிறதா?"},{"de":"Kann ich Überweisungen auch mit dem Handy machen?","en":"Can I also make transfers with my phone?","ta":"என் மொபைல் ஃபோன் மூலமும் பணப் பரிமாற்றம் செய்ய முடியுமா?"}],"tip":"die Überweisung = bank transfer. das Handy = mobile phone; mit dem Handy (Dativ)."},{"tutor":"Ja, mit unserer App können Sie alles erledigen: Überweisungen, Kontostand, Daueraufträge. Die Zugangsdaten kommen per Post. Jetzt brauche ich noch Ihren Pass und Ihre Meldebescheinigung.","tutor_en":"Yes, you can do everything with our app: transfers, balance, standing orders. The login details come by post. Now I just need your passport and your registration certificate.","tutor_ta":"ஆம், எங்கள் ஆப் மூலம் எல்லாவற்றையும் செய்யலாம்: பணப் பரிமாற்றம், கணக்கு இருப்பு, நிலையான கட்டளைகள். உள்நுழைவு விவரங்கள் தபாலில் வரும். இப்போது எனக்கு உங்கள் பாஸ்போர்ட்டும் பதிவுச் சான்றிதழும் மட்டும் தேவை.","task_en":"Hand over your documents","task_ta":"உங்கள் ஆவணங்களைக் கொடுங்கள்","goal":null,"options":[{"de":"Hier, bitte schön.","en":"Here you are.","ta":"இதோ, எடுத்துக்கொள்ளுங்கள்."},{"de":"Hier sind mein Pass und die Meldebescheinigung.","en":"Here are my passport and the registration certificate.","ta":"இதோ என் பாஸ்போர்ட்டும் பதிவுச் சான்றிதழும்."},{"de":"Bitte schön. Brauchen Sie auch meinen Arbeitsvertrag?","en":"Here you are. Do you also need my employment contract?","ta":"இதோ. உங்களுக்கு என் வேலை ஒப்பந்தமும் தேவையா?"}],"tip":"Two things → plural verb: Hier sind ... brauchen + Akkusativ: meinen Arbeitsvertrag (der → meinen)."}],"end":"Danke, der Pass und die Meldebescheinigung reichen. So, Ihr Konto ist eröffnet – herzlich willkommen bei uns!","end_en":"Thank you, the passport and the registration certificate are enough. There, your account is open – welcome to our bank!","end_ta":"நன்றி, பாஸ்போர்ட்டும் பதிவுச் சான்றிதழும் போதும். சரி, உங்கள் கணக்கு தொடங்கப்பட்டுவிட்டது – எங்கள் வங்கிக்கு அன்புடன் வரவேற்கிறோம்!","words":[{"de":"das Girokonto","en":"the current account"},{"de":"ein Konto eröffnen","en":"to open an account"},{"de":"die Gebühr","en":"the fee"},{"de":"die Bankkarte","en":"the bank card"},{"de":"die Überweisung","en":"the bank transfer"},{"de":"der Kontostand","en":"the account balance"},{"de":"der Geldautomat","en":"the cash machine"},{"de":"die Filiale","en":"the branch"}]},
"reklamation":{"turns":[{"tutor":"Guten Tag! Kann ich Ihnen helfen?","tutor_en":"Hello! Can I help you?","tutor_ta":"வணக்கம்! நான் உங்களுக்கு உதவலாமா?","task_en":"Say that you have a problem with something you bought","task_ta":"நீங்கள் வாங்கிய ஒரு பொருளில் பிரச்சினை இருப்பதாகச் சொல்லுங்கள்","goal":0,"options":[{"de":"Ja, ich möchte etwas reklamieren.","en":"Yes, I'd like to make a complaint about something.","ta":"ஆம், நான் ஒரு பொருள் பற்றிப் புகார் செய்ய விரும்புகிறேன்."},{"de":"Ja, ich habe ein Problem mit diesen Kopfhörern.","en":"Yes, I have a problem with these headphones.","ta":"ஆம், இந்த ஹெட்ஃபோன்களில் எனக்கு ஒரு பிரச்சினை இருக்கிறது."},{"de":"Ja, bitte. Ich habe hier letzte Woche diesen Wasserkocher gekauft.","en":"Yes, please. I bought this kettle here last week.","ta":"ஆம், தயவுசெய்து. கடந்த வாரம் இந்த மின்சாரக் கெட்டிலை இங்கே வாங்கினேன்."}],"tip":"reklamieren = to return/complain about a faulty product. mit + Dativ plural: mit diesen Kopfhörern (-n)."},{"tutor":"Oh, das tut mir leid. Was genau funktioniert denn nicht?","tutor_en":"Oh, I'm sorry about that. What exactly isn't working?","tutor_ta":"ஓ, அதற்கு வருந்துகிறேன். சரியாக எது வேலை செய்யவில்லை?","task_en":"Explain the problem with the device","task_ta":"சாதனத்தில் உள்ள பிரச்சினையை விளக்குங்கள்","goal":0,"options":[{"de":"Das Gerät geht nicht mehr an.","en":"The device doesn't switch on any more.","ta":"சாதனம் இனி ஆன் ஆகவில்லை."},{"de":"Es funktioniert seit gestern nicht mehr richtig.","en":"It hasn't worked properly since yesterday.","ta":"நேற்றிலிருந்து அது சரியாக வேலை செய்யவில்லை."},{"de":"Es lädt nicht, obwohl ich ein anderes Kabel probiert habe.","en":"It doesn't charge, although I tried another cable.","ta":"நான் வேறு கேபிளை முயற்சித்தும் அது சார்ஜ் ஆகவில்லை."}],"tip":"angehen (separable) = to switch on: Es geht nicht an. obwohl sends the verb to the end: ... probiert habe."},{"tutor":"Hm, das ist ärgerlich. Wann haben Sie das Gerät gekauft? Haben Sie den Kassenbon dabei?","tutor_en":"Hm, that's annoying. When did you buy the device? Do you have the receipt with you?","tutor_ta":"ம்ம், அது எரிச்சலானதுதான். சாதனத்தை எப்போது வாங்கினீர்கள்? ரசீது உங்களிடம் இருக்கிறதா?","task_en":"Say when you bought it and show the receipt","task_ta":"எப்போது வாங்கினீர்கள் என்று சொல்லி, ரசீதைக் காட்டுங்கள்","goal":0,"options":[{"de":"Vor zwei Wochen. Hier ist der Kassenbon.","en":"Two weeks ago. Here is the receipt.","ta":"இரண்டு வாரங்களுக்கு முன்பு. இதோ ரசீது."},{"de":"Letzten Samstag. Den Bon habe ich dabei.","en":"Last Saturday. I have the receipt with me.","ta":"கடந்த சனிக்கிழமை. ரசீது என்னிடம் இருக்கிறது."},{"de":"Vor zehn Tagen, hier in dieser Filiale. Hier ist die Quittung.","en":"Ten days ago, here in this branch. Here is the receipt.","ta":"பத்து நாட்களுக்கு முன்பு, இதே கிளையில். இதோ ரசீது."}],"tip":"vor + Dativ = ago: vor zwei Wochen. der Kassenbon / der Bon / die Quittung all mean receipt."},{"tutor":"Danke. Und was möchten Sie jetzt – einen Umtausch oder Ihr Geld zurück?","tutor_en":"Thank you. And what would you like now – an exchange or your money back?","tutor_ta":"நன்றி. இப்போது உங்களுக்கு என்ன வேண்டும் – மாற்றுப் பொருளா அல்லது உங்கள் பணம் திரும்பவா?","task_en":"Say what you want: an exchange or a refund","task_ta":"உங்களுக்கு என்ன வேண்டும் என்று சொல்லுங்கள்: மாற்றுப் பொருளா அல்லது பணம் திரும்பவா","goal":1,"options":[{"de":"Ich möchte bitte mein Geld zurück.","en":"I'd like my money back, please.","ta":"எனக்கு என் பணம் திரும்ப வேண்டும், தயவுசெய்து."},{"de":"Ich hätte gern ein neues Gerät.","en":"I'd like a new device.","ta":"எனக்கு ஒரு புதிய சாதனம் வேண்டும்."},{"de":"Am liebsten würde ich es gegen ein neues umtauschen.","en":"Ideally I'd like to exchange it for a new one.","ta":"முடிந்தால் அதை ஒரு புதியதாக மாற்றிக்கொள்ள விரும்புகிறேன்."}],"tip":"ich hätte gern = I would like (polite). umtauschen gegen + Akkusativ = to exchange for."},{"tutor":"Ich verstehe. Leider müssen wir das Gerät zuerst zur Reparatur schicken. Das dauert etwa zwei Wochen.","tutor_en":"I understand. Unfortunately we first have to send the device for repair. That takes about two weeks.","tutor_ta":"புரிகிறது. துரதிர்ஷ்டவசமாக, முதலில் சாதனத்தைப் பழுதுபார்க்க அனுப்ப வேண்டும். அதற்குச் சுமார் இரண்டு வாரங்கள் ஆகும்.","task_en":"React politely to the suggestion","task_ta":"அந்தப் பரிந்துரைக்கு மரியாதையாகப் பதில் சொல்லுங்கள்","goal":2,"options":[{"de":"Schade, aber das ist in Ordnung.","en":"A pity, but that's okay.","ta":"வருத்தம்தான், ஆனால் பரவாயில்லை."},{"de":"Zwei Wochen sind lang. Gibt es keine andere Lösung?","en":"Two weeks is long. Is there no other solution?","ta":"இரண்டு வாரங்கள் அதிகம். வேறு தீர்வு எதுவும் இல்லையா?"},{"de":"Ich verstehe, aber ich brauche das Gerät dringend.","en":"I understand, but I urgently need the device.","ta":"புரிகிறது, ஆனால் எனக்கு அந்தச் சாதனம் அவசரமாகத் தேவை."}],"tip":"Polite disagreement: Ich verstehe, aber ... / Gibt es keine andere Lösung? Schade = what a pity."},{"tutor":"Ich kann Ihnen etwas anbieten: Sie bekommen so lange ein Ersatzgerät. Wäre das in Ordnung für Sie?","tutor_en":"I can offer you something: you get a replacement device in the meantime. Would that be okay for you?","tutor_ta":"நான் உங்களுக்கு ஒன்று தரலாம்: அதுவரை உங்களுக்கு ஒரு மாற்றுச் சாதனம் கிடைக்கும். அது உங்களுக்குச் சரியா?","task_en":"Accept the offer politely","task_ta":"அந்த வாய்ப்பை மரியாதையாக ஏற்றுக்கொள்ளுங்கள்","goal":2,"options":[{"de":"Ja, das ist eine gute Lösung.","en":"Yes, that's a good solution.","ta":"ஆம், அது நல்ல தீர்வு."},{"de":"Das ist sehr nett von Ihnen, danke.","en":"That's very kind of you, thank you.","ta":"நீங்கள் மிகவும் அன்பானவர், நன்றி."},{"de":"Ja, damit bin ich einverstanden. Vielen Dank für Ihre Hilfe.","en":"Yes, I agree to that. Thank you very much for your help.","ta":"ஆம், அதற்கு நான் சம்மதிக்கிறேன். உங்கள் உதவிக்கு மிக்க நன்றி."}],"tip":"einverstanden sein mit + Dativ = to agree to (damit = with that). nett von Ihnen = kind of you."},{"tutor":"Gern. Dann brauche ich nur noch Ihren Namen und Ihre Telefonnummer, damit wir Sie anrufen können.","tutor_en":"You're welcome. Then I just need your name and your phone number so that we can call you.","tutor_ta":"சரி. அப்படியானால் உங்களை அழைக்க எனக்கு உங்கள் பெயரும் தொலைபேசி எண்ணும் மட்டும் தேவை.","task_en":"Give your name and offer your phone number","task_ta":"உங்கள் பெயரைச் சொல்லி, உங்கள் தொலைபேசி எண்ணைக் கொடுங்கள்","goal":null,"options":[{"de":"Mein Name ist Priya Kumar.","en":"My name is Priya Kumar.","ta":"என் பெயர் பிரியா குமார்."},{"de":"Mein Name ist Kumar. Soll ich die Nummer aufschreiben?","en":"My name is Kumar. Shall I write the number down?","ta":"என் பெயர் குமார். எண்ணை நான் எழுதித் தரட்டுமா?"},{"de":"Ich heiße Arun Kumar, und hier ist meine Handynummer.","en":"My name is Arun Kumar, and here is my mobile number.","ta":"என் பெயர் அருண் குமார், இதோ என் மொபைல் எண்."}],"tip":"Soll ich ...? = Shall I ...? (an offer). Mein Name ist ... is more formal than Ich heiße ... ; die Handynummer = mobile number."}],"end":"Danke! Schreiben Sie Ihre Nummer bitte hier auf das Formular. Hier ist Ihr Ersatzgerät – wir melden uns, sobald die Reparatur fertig ist.","end_en":"Thank you! Please write your number here on the form. Here is your replacement device – we'll be in touch as soon as the repair is done.","end_ta":"நன்றி! தயவுசெய்து உங்கள் எண்ணை இந்தப் படிவத்தில் எழுதுங்கள். இதோ உங்கள் மாற்றுச் சாதனம் – பழுதுபார்ப்பு முடிந்ததும் உங்களைத் தொடர்புகொள்வோம்.","words":[{"de":"reklamieren","en":"to complain about a faulty product"},{"de":"der Kassenbon","en":"the receipt"},{"de":"der Umtausch","en":"the exchange"},{"de":"umtauschen","en":"to exchange"},{"de":"die Reparatur","en":"the repair"},{"de":"das Ersatzgerät","en":"the replacement device"},{"de":"die Garantie","en":"the warranty"},{"de":"einverstanden sein","en":"to agree"}]},
"bewerbung":{"turns":[{"tutor":"Guten Tag, schön, dass Sie da sind! Haben Sie gut zu uns gefunden?","tutor_en":"Hello, nice that you're here! Did you find your way to us easily?","tutor_ta":"வணக்கம், நீங்கள் வந்தது மகிழ்ச்சி! எங்கள் இடத்தை எளிதாகக் கண்டுபிடித்தீர்களா?","task_en":"Answer politely and briefly","task_ta":"மரியாதையாகவும் சுருக்கமாகவும் பதில் சொல்லுங்கள்","goal":null,"options":[{"de":"Ja, danke, ohne Probleme.","en":"Yes, thanks, without any problems.","ta":"ஆம், நன்றி, எந்தப் பிரச்சினையும் இல்லாமல்."},{"de":"Ja, ich bin mit der U-Bahn gekommen.","en":"Yes, I came by underground.","ta":"ஆம், நான் மெட்ரோ ரயிலில் வந்தேன்."},{"de":"Ja, danke. Ich war sogar ein bisschen zu früh.","en":"Yes, thanks. I was even a little early.","ta":"ஆம், நன்றி. நான் கொஞ்சம் முன்னதாகவே வந்துவிட்டேன்."}],"tip":"mit + Dativ for transport: mit der U-Bahn, mit dem Bus. kommen takes sein: Ich bin gekommen."},{"tutor":"Wunderbar. Erzählen Sie doch bitte zuerst etwas über sich.","tutor_en":"Wonderful. Please tell me a little about yourself first.","tutor_ta":"அருமை. முதலில் உங்களைப் பற்றிக் கொஞ்சம் சொல்லுங்கள்.","task_en":"Introduce yourself","task_ta":"உங்களை அறிமுகப்படுத்துங்கள்","goal":0,"options":[{"de":"Ich heiße Arun und komme aus Chennai.","en":"My name is Arun and I come from Chennai.","ta":"என் பெயர் அருண், நான் சென்னையிலிருந்து வருகிறேன்."},{"de":"Mein Name ist Priya, ich bin 29 und Softwareentwicklerin.","en":"My name is Priya, I'm 29 and a software developer.","ta":"என் பெயர் பிரியா, எனக்கு 29 வயது, நான் மென்பொருள் உருவாக்குநர்."},{"de":"Ich komme aus Indien und lebe seit einem Jahr in Deutschland.","en":"I come from India and have been living in Germany for a year.","ta":"நான் இந்தியாவிலிருந்து வருகிறேன், ஒரு வருடமாக ஜெர்மனியில் வசிக்கிறேன்."}],"tip":"Professions without an article: Ich bin Softwareentwicklerin. seit + Dativ + present tense: Ich lebe seit einem Jahr hier."},{"tutor":"Sehr schön. Und welche Berufserfahrung haben Sie?","tutor_en":"Very nice. And what work experience do you have?","tutor_ta":"மிகவும் நல்லது. உங்களுக்கு என்ன பணி அனுபவம் இருக்கிறது?","task_en":"Talk about your work experience","task_ta":"உங்கள் பணி அனுபவம் பற்றிப் பேசுங்கள்","goal":0,"options":[{"de":"Ich habe fünf Jahre als Krankenpfleger gearbeitet.","en":"I worked as a nurse for five years.","ta":"நான் ஐந்து ஆண்டுகள் செவிலியராக வேலை செய்தேன்."},{"de":"Ich habe drei Jahre bei einer IT-Firma in Chennai gearbeitet.","en":"I worked at an IT company in Chennai for three years.","ta":"நான் சென்னையில் ஒரு ஐடி நிறுவனத்தில் மூன்று ஆண்டுகள் வேலை செய்தேன்."},{"de":"Nach meinem Studium war ich vier Jahre im Kundenservice tätig.","en":"After my studies I worked in customer service for four years.","ta":"என் படிப்புக்குப் பிறகு நான்கு ஆண்டுகள் வாடிக்கையாளர் சேவையில் பணியாற்றினேன்."}],"tip":"als + profession (no article): als Krankenpfleger. bei + company: bei einer IT-Firma. tätig sein = to work (formal)."},{"tutor":"Interessant! Was sind Ihre Stärken?","tutor_en":"Interesting! What are your strengths?","tutor_ta":"சுவாரஸ்யம்! உங்கள் பலங்கள் என்ன?","task_en":"Name your strengths","task_ta":"உங்கள் பலங்களைச் சொல்லுங்கள்","goal":1,"options":[{"de":"Ich bin zuverlässig und arbeite gern im Team.","en":"I'm reliable and like working in a team.","ta":"நான் நம்பகமானவன்/நம்பகமானவள், குழுவாக வேலை செய்ய விரும்புகிறேன்."},{"de":"Ich bin sehr organisiert und lerne schnell.","en":"I'm very organised and learn quickly.","ta":"நான் மிகவும் ஒழுங்கானவன்/ஒழுங்கானவள், விரைவாகக் கற்றுக்கொள்வேன்."},{"de":"Ich kann gut mit Stress umgehen und bleibe immer freundlich.","en":"I handle stress well and always stay friendly.","ta":"என்னால் மன அழுத்தத்தை நன்றாகச் சமாளிக்க முடியும், எப்போதும் அன்பாக இருப்பேன்."}],"tip":"umgehen mit + Dativ = to deal with: mit Stress umgehen. gern + verb = like doing: arbeite gern."},{"tutor":"Und gibt es auch etwas, das Sie verbessern möchten?","tutor_en":"And is there also something you would like to improve?","tutor_ta":"நீங்கள் மேம்படுத்த விரும்பும் ஏதாவது இருக்கிறதா?","task_en":"Name a weakness in a positive way","task_ta":"உங்கள் ஒரு பலவீனத்தை நேர்மறையாகச் சொல்லுங்கள்","goal":null,"options":[{"de":"Manchmal bin ich zu ungeduldig.","en":"Sometimes I'm too impatient.","ta":"சில நேரங்களில் நான் அதிகப் பொறுமையின்றி இருப்பேன்."},{"de":"Mein Deutsch ist noch nicht perfekt, aber ich lerne jeden Tag.","en":"My German isn't perfect yet, but I study every day.","ta":"என் ஜெர்மன் இன்னும் சரியாக இல்லை, ஆனால் நான் தினமும் கற்கிறேன்."},{"de":"Ich bin manchmal zu perfektionistisch, aber ich arbeite daran.","en":"I'm sometimes too much of a perfectionist, but I'm working on it.","ta":"நான் சில நேரங்களில் மிகவும் பரிபூரணவாதியாக இருப்பேன், ஆனால் அதைச் சரிசெய்ய முயல்கிறேன்."}],"tip":"arbeiten an + Dativ → daran arbeiten = to work on it. Time words (manchmal) can start the sentence: verb second."},{"tutor":"Danke für Ihre Offenheit. Warum möchten Sie gerade bei uns arbeiten?","tutor_en":"Thank you for your openness. Why do you want to work for us in particular?","tutor_ta":"உங்கள் வெளிப்படைத்தன்மைக்கு நன்றி. நீங்கள் குறிப்பாக எங்களிடம் ஏன் வேலை செய்ய விரும்புகிறீர்கள்?","task_en":"Explain why you want this job","task_ta":"இந்த வேலை உங்களுக்கு ஏன் வேண்டும் என்று விளக்குங்கள்","goal":2,"options":[{"de":"Ihre Firma hat einen sehr guten Ruf.","en":"Your company has a very good reputation.","ta":"உங்கள் நிறுவனத்துக்கு மிக நல்ல பெயர் இருக்கிறது."},{"de":"Die Stelle passt sehr gut zu meiner Erfahrung.","en":"The position fits my experience very well.","ta":"இந்தப் பணி என் அனுபவத்துக்கு மிகவும் பொருத்தமானது."},{"de":"Ich möchte mich weiterentwickeln, und Ihr Team arbeitet international.","en":"I want to keep developing, and your team works internationally.","ta":"நான் மேலும் வளர விரும்புகிறேன், உங்கள் குழு சர்வதேச அளவில் வேலை செய்கிறது."}],"tip":"passen zu + Dativ: zu meiner Erfahrung. sich weiterentwickeln = to develop (professionally)."},{"tutor":"Das klingt überzeugend. Haben Sie noch Fragen an uns?","tutor_en":"That sounds convincing. Do you have any questions for us?","tutor_ta":"அது நம்பத்தகுந்ததாக இருக்கிறது. எங்களிடம் கேட்க உங்களுக்கு ஏதாவது கேள்விகள் உள்ளனவா?","task_en":"Ask your own question about the job","task_ta":"வேலை பற்றி உங்கள் சொந்தக் கேள்வியைக் கேளுங்கள்","goal":3,"options":[{"de":"Ja. Wie sind die Arbeitszeiten?","en":"Yes. What are the working hours?","ta":"ஆம். வேலை நேரம் எப்படி?"},{"de":"Kann man auch im Homeoffice arbeiten?","en":"Can you also work from home?","ta":"வீட்டிலிருந்தும் வேலை செய்ய முடியுமா?"},{"de":"Wie sieht ein typischer Arbeitstag in Ihrem Team aus?","en":"What does a typical working day look like in your team?","ta":"உங்கள் குழுவில் ஒரு சாதாரண வேலை நாள் எப்படி இருக்கும்?"}],"tip":"aussehen is separable: Wie sieht ... aus? man = one/you in general: Kann man ...?"},{"tutor":"Gute Frage – das erkläre ich Ihnen gleich genauer. Vorher noch eine Frage: Ab wann könnten Sie bei uns anfangen?","tutor_en":"Good question – I'll explain that in more detail in a moment. But first one more question: from when could you start with us?","tutor_ta":"நல்ல கேள்வி – அதை இன்னும் சிறிது நேரத்தில் விரிவாக விளக்குகிறேன். அதற்கு முன் ஒரு கேள்வி: நீங்கள் எப்போதிலிருந்து எங்களிடம் வேலை தொடங்க முடியும்?","task_en":"Say when you could start","task_ta":"நீங்கள் எப்போது வேலையைத் தொடங்க முடியும் என்று சொல்லுங்கள்","goal":null,"options":[{"de":"Ab dem ersten November.","en":"From the first of November.","ta":"நவம்பர் ஒன்றாம் தேதியிலிருந்து."},{"de":"Ich könnte sofort anfangen.","en":"I could start straight away.","ta":"நான் உடனே தொடங்க முடியும்."},{"de":"Ich habe drei Monate Kündigungsfrist, also ab Januar.","en":"I have three months' notice, so from January.","ta":"எனக்கு மூன்று மாத அறிவிப்புக் காலம் இருக்கிறது, ஆகவே ஜனவரியிலிருந்து."}],"tip":"ab + Dativ = from (a point in time): ab dem ersten November. die Kündigungsfrist = notice period."}],"end":"Vielen Dank für das Gespräch! Wir melden uns bis Ende nächster Woche bei Ihnen.","end_en":"Thank you very much for the interview! We'll get back to you by the end of next week.","end_ta":"இந்த நேர்காணலுக்கு மிக்க நன்றி! அடுத்த வார இறுதிக்குள் உங்களைத் தொடர்புகொள்வோம்.","words":[{"de":"das Vorstellungsgespräch","en":"the job interview"},{"de":"die Berufserfahrung","en":"the work experience"},{"de":"die Stärke","en":"the strength"},{"de":"die Schwäche","en":"the weakness"},{"de":"die Stelle","en":"the position, job"},{"de":"zuverlässig","en":"reliable"},{"de":"die Arbeitszeit","en":"the working hours"},{"de":"die Kündigungsfrist","en":"the notice period"}]},
"meinung":{"turns":[{"tutor":"Hallo! Unser Thema heute: Lebt man besser in der Stadt oder auf dem Land? Was meinst du?","tutor_en":"Hello! Our topic today: is life better in the city or in the countryside? What do you think?","tutor_ta":"வணக்கம்! இன்றைய தலைப்பு: நகரத்தில் வாழ்வது நல்லதா, கிராமத்தில் வாழ்வது நல்லதா? நீ என்ன நினைக்கிறாய்?","task_en":"Give your opinion","task_ta":"உங்கள் கருத்தைச் சொல்லுங்கள்","goal":0,"options":[{"de":"Ich finde, man lebt besser in der Stadt.","en":"I think life is better in the city.","ta":"நகரத்தில் வாழ்வதே நல்லது என்று நான் நினைக்கிறேன்."},{"de":"Meiner Meinung nach ist das Leben auf dem Land schöner.","en":"In my opinion, life in the countryside is nicer.","ta":"என் கருத்துப்படி, கிராம வாழ்க்கை இன்னும் அழகானது."},{"de":"Ich lebe lieber in der Stadt, weil dort mehr los ist.","en":"I prefer living in the city because more is going on there.","ta":"நகரத்தில் அதிகம் நடப்பதால், நான் அங்கே வாழவே விரும்புகிறேன்."}],"tip":"Meiner Meinung nach + verb second (ist). weil sends the verb to the end (los ist). lieber = rather, prefer."},{"tutor":"Interessant. Und warum siehst du das so?","tutor_en":"Interesting. And why do you see it that way?","tutor_ta":"சுவாரஸ்யம். நீ ஏன் அப்படி நினைக்கிறாய்?","task_en":"Give a reason for your opinion","task_ta":"உங்கள் கருத்துக்கு ஒரு காரணம் சொல்லுங்கள்","goal":0,"options":[{"de":"Weil es dort mehr Arbeitsplätze gibt.","en":"Because there are more jobs there.","ta":"ஏனென்றால் அங்கே அதிக வேலை வாய்ப்புகள் இருக்கின்றன."},{"de":"Auf dem Land ist es ruhiger, und die Luft ist sauberer.","en":"In the countryside it's quieter and the air is cleaner.","ta":"கிராமத்தில் அமைதி அதிகம், காற்றும் சுத்தமாக இருக்கும்."},{"de":"In der Stadt sind Schulen, Ärzte und Geschäfte ganz in der Nähe.","en":"In the city, schools, doctors and shops are very close by.","ta":"நகரத்தில் பள்ளிகள், மருத்துவர்கள், கடைகள் எல்லாம் மிக அருகிலேயே உள்ளன."}],"tip":"Comparatives: ruhig → ruhiger, sauber → sauberer. es gibt + Akkusativ = there is/are."},{"tutor":"Kannst du ein Beispiel aus deinem Leben nennen?","tutor_en":"Can you give an example from your own life?","tutor_ta":"உன் வாழ்க்கையிலிருந்து ஒரு உதாரணம் சொல்ல முடியுமா?","task_en":"Give an example from your life","task_ta":"உங்கள் வாழ்க்கையிலிருந்து ஒரு உதாரணம் சொல்லுங்கள்","goal":1,"options":[{"de":"In Berlin brauche ich zum Beispiel kein Auto.","en":"In Berlin, for example, I don't need a car.","ta":"உதாரணமாக, பெர்லினில் எனக்குக் கார் தேவையில்லை."},{"de":"Zum Beispiel ist meine Heimatstadt Chennai sehr laut und voll.","en":"For example, my home town Chennai is very loud and crowded.","ta":"உதாரணமாக, என் சொந்த ஊரான சென்னை மிகவும் சத்தமாகவும் நெரிசலாகவும் இருக்கிறது."},{"de":"Als Kind habe ich bei meinen Großeltern im Dorf gewohnt.","en":"As a child I lived with my grandparents in the village.","ta":"சிறு வயதில் நான் கிராமத்தில் என் தாத்தா பாட்டியுடன் வசித்தேன்."}],"tip":"Zum Beispiel at the start counts as position 1, so the verb comes next: Zum Beispiel ist ... bei + person = at someone's home."},{"tutor":"Das verstehe ich. Aber beide Seiten haben Nachteile: In der Stadt sind die Mieten sehr hoch, und auf dem Land fährt oft kaum ein Bus. Was sagst du dazu?","tutor_en":"I understand. But both sides have disadvantages: in the city rents are very high, and in the countryside there's often hardly a bus. What do you say to that?","tutor_ta":"எனக்குப் புரிகிறது. ஆனால் இரண்டிலும் குறைகள் உண்டு: நகரத்தில் வாடகை மிக அதிகம், கிராமத்தில் பெரும்பாலும் பேருந்தே அரிதாகத்தான் வரும். இதற்கு நீ என்ன சொல்கிறாய்?","task_en":"React to the counter-argument","task_ta":"எதிர்வாதத்துக்குப் பதில் சொல்லுங்கள்","goal":2,"options":[{"de":"Das stimmt, aber für mich ist das kein Problem.","en":"That's true, but for me that's not a problem.","ta":"அது உண்மைதான், ஆனால் எனக்கு அது ஒரு பிரச்சினை இல்லை."},{"de":"Da hast du recht. Trotzdem bleibe ich bei meiner Meinung.","en":"You're right there. Still, I stick to my opinion.","ta":"நீ சொல்வது சரிதான். இருந்தாலும் நான் என் கருத்திலேயே இருக்கிறேன்."},{"de":"Das ist ein guter Punkt, aber jeder Ort hat Vor- und Nachteile.","en":"That's a good point, but every place has pros and cons.","ta":"அது நல்ல கருத்து, ஆனால் ஒவ்வொரு இடத்துக்கும் நன்மைகளும் குறைகளும் உண்டு."}],"tip":"Reacting: Das stimmt, aber ... / Da hast du recht. trotzdem (= still) takes position 1, so the verb follows: Trotzdem bleibe ich ..."},{"tutor":"Und was ist mit Familien mit Kindern? Wo ist es für sie besser?","tutor_en":"And what about families with children? Where is it better for them?","tutor_ta":"குழந்தைகள் உள்ள குடும்பங்களுக்கு எப்படி? அவர்களுக்கு எங்கே நல்லது?","task_en":"Say where it's better for families and why","task_ta":"குடும்பங்களுக்கு எங்கே நல்லது, ஏன் என்று சொல்லுங்கள்","goal":0,"options":[{"de":"Ich glaube, auf dem Land ist es für Kinder besser.","en":"I think it's better for children in the countryside.","ta":"குழந்தைகளுக்குக் கிராமமே நல்லது என்று நான் நினைக்கிறேன்."},{"de":"In der Stadt, weil es dort mehr Schulen und Angebote gibt.","en":"In the city, because there are more schools and activities there.","ta":"நகரத்தில்தான், ஏனென்றால் அங்கே அதிகப் பள்ளிகளும் வசதிகளும் உள்ளன."},{"de":"Das hängt von der Familie ab, aber Kinder brauchen Natur.","en":"That depends on the family, but children need nature.","ta":"அது குடும்பத்தைப் பொறுத்தது, ஆனால் குழந்தைகளுக்கு இயற்கை தேவை."}],"tip":"abhängen von + Dativ = to depend on: Das hängt von der Familie ab (separable verb, ab at the end)."},{"tutor":"Wie wäre es mit einem Kompromiss – zum Beispiel am Stadtrand wohnen?","tutor_en":"How about a compromise – for example living on the edge of the city?","tutor_ta":"ஒரு சமரசம் எப்படி – உதாரணமாக நகரத்தின் புறநகர்ப் பகுதியில் வசிப்பது?","task_en":"React to your partner's suggestion","task_ta":"உங்கள் உரையாடல் துணையின் பரிந்துரைக்குப் பதில் சொல்லுங்கள்","goal":2,"options":[{"de":"Das ist eine gute Idee.","en":"That's a good idea.","ta":"அது நல்ல யோசனை."},{"de":"Ja, am Stadtrand hat man Ruhe und trotzdem gute Verbindungen.","en":"Yes, on the edge of the city you have peace and still good connections.","ta":"ஆம், புறநகரில் அமைதியும் கிடைக்கும், நல்ல போக்குவரத்து இணைப்புகளும் இருக்கும்."},{"de":"Vielleicht, aber dann muss man jeden Tag lange pendeln.","en":"Maybe, but then you have to commute a long way every day.","ta":"இருக்கலாம், ஆனால் அப்போது தினமும் நீண்ட தூரம் பயணம் செய்ய வேண்டியிருக்கும்."}],"tip":"pendeln = to commute. Modal verb + infinitive at the end: muss ... pendeln. man = you/one in general."},{"tutor":"Unsere Zeit ist fast um. Kannst du deine Meinung kurz zusammenfassen?","tutor_en":"Our time is almost up. Can you briefly sum up your opinion?","tutor_ta":"நம் நேரம் கிட்டத்தட்ட முடிந்துவிட்டது. உன் கருத்தைச் சுருக்கமாகச் சொல்ல முடியுமா?","task_en":"Summarise your opinion","task_ta":"உங்கள் கருத்தைச் சுருக்கமாகச் சொல்லுங்கள்","goal":3,"options":[{"de":"Zusammenfassend finde ich die Stadt besser.","en":"To sum up, I think the city is better.","ta":"சுருக்கமாகச் சொன்னால், நகரமே நல்லது என்று நினைக்கிறேன்."},{"de":"Für mich ist das Land besser, aber die Stadt hat auch Vorteile.","en":"For me the countryside is better, but the city has advantages too.","ta":"எனக்குக் கிராமமே நல்லது, ஆனால் நகரத்துக்கும் நன்மைகள் உண்டு."},{"de":"Insgesamt denke ich: Jeder muss den richtigen Ort für sich finden.","en":"Overall I think: everyone has to find the right place for themselves.","ta":"மொத்தத்தில் நான் நினைப்பது: ஒவ்வொருவரும் தனக்கு ஏற்ற இடத்தைக் கண்டுபிடிக்க வேண்டும்."}],"tip":"Summing up: Zusammenfassend ... / Insgesamt ... – both take position 1, so the verb comes second."}],"end":"Danke, das war eine gute Diskussion! Wir sehen es teilweise ähnlich, teilweise anders – und das ist völlig in Ordnung.","end_en":"Thanks, that was a good discussion! We partly see it the same way and partly differently – and that's completely fine.","end_ta":"நன்றி, அது ஒரு நல்ல விவாதம்! சில விஷயங்களில் நாம் ஒத்துப்போகிறோம், சிலவற்றில் வேறுபடுகிறோம் – அது முற்றிலும் சரிதான்.","words":[{"de":"die Meinung","en":"the opinion"},{"de":"meiner Meinung nach","en":"in my opinion"},{"de":"der Vorteil","en":"the advantage"},{"de":"der Nachteil","en":"the disadvantage"},{"de":"die Miete","en":"the rent"},{"de":"pendeln","en":"to commute"},{"de":"Da hast du recht.","en":"You're right there."},{"de":"zusammenfassend","en":"to sum up"}]},
"frei":{"turns":[{"tutor":"Hallo! Schön, dich kennenzulernen. Worüber möchtest du heute sprechen: Hobbys, Essen oder das Leben in Deutschland?","tutor_en":"Hello! Nice to meet you. What would you like to talk about today: hobbies, food or life in Germany?","tutor_ta":"வணக்கம்! உன்னைச் சந்தித்ததில் மகிழ்ச்சி. இன்று எதைப் பற்றிப் பேச விரும்புகிறாய்: பொழுதுபோக்குகள், உணவு, அல்லது ஜெர்மனியில் வாழ்க்கை?","task_en":"Choose a topic","task_ta":"ஒரு தலைப்பைத் தேர்ந்தெடுங்கள்","goal":0,"options":[{"de":"Lass uns über Hobbys sprechen.","en":"Let's talk about hobbies.","ta":"பொழுதுபோக்குகள் பற்றிப் பேசலாம்."},{"de":"Ich möchte gern über Essen sprechen.","en":"I'd like to talk about food.","ta":"நான் உணவு பற்றிப் பேச விரும்புகிறேன்."},{"de":"Vielleicht über das Leben in Deutschland?","en":"Maybe about life in Germany?","ta":"ஜெர்மனியில் வாழ்க்கை பற்றிப் பேசலாமா?"}],"tip":"sprechen über + Akkusativ = to talk about. Lass uns ... = Let's ..."},{"tutor":"Super, dann sprechen wir einfach ein bisschen über alles! Zuerst: Was machst du gern in deiner Freizeit?","tutor_en":"Great, then let's just talk a bit about everything! First: what do you like doing in your free time?","tutor_ta":"அருமை, அப்படியானால் எல்லாவற்றையும் பற்றிக் கொஞ்சம் பேசலாம்! முதலில்: ஓய்வு நேரத்தில் நீ என்ன செய்ய விரும்புகிறாய்?","task_en":"Talk about your hobbies","task_ta":"உங்கள் பொழுதுபோக்குகள் பற்றிப் பேசுங்கள்","goal":1,"options":[{"de":"Ich koche gern und spiele Cricket.","en":"I like cooking and I play cricket.","ta":"எனக்குச் சமைக்கப் பிடிக்கும், நான் கிரிக்கெட் விளையாடுவேன்."},{"de":"In meiner Freizeit lese ich gern Bücher.","en":"In my free time I like reading books.","ta":"ஓய்வு நேரத்தில் புத்தகங்கள் படிக்க எனக்குப் பிடிக்கும்."},{"de":"Ich gehe gern spazieren und höre viel Musik.","en":"I like going for walks and listen to a lot of music.","ta":"எனக்கு நடைப்பயிற்சி செல்லப் பிடிக்கும், நிறைய இசை கேட்பேன்."}],"tip":"gern after the verb = like doing: Ich koche gern. In meiner Freizeit + verb second: ... lese ich."},{"tutor":"Schön! Ich mache viel Sport, vor allem Schwimmen.","tutor_en":"Nice! I do a lot of sport, especially swimming.","tutor_ta":"நல்லது! நான் நிறைய விளையாட்டுப் பயிற்சி செய்வேன், குறிப்பாக நீச்சல்.","task_en":"Ask your partner a question about swimming","task_ta":"நீச்சல் பற்றி உங்கள் துணையிடம் ஒரு கேள்வி கேளுங்கள்","goal":2,"options":[{"de":"Wie oft gehst du schwimmen?","en":"How often do you go swimming?","ta":"நீ எவ்வளவு அடிக்கடி நீச்சலுக்குப் போவாய்?"},{"de":"Wo gehst du schwimmen?","en":"Where do you go swimming?","ta":"நீ எங்கே நீச்சலுக்குப் போவாய்?"},{"de":"Seit wann schwimmst du schon?","en":"How long have you been swimming?","ta":"நீ எவ்வளவு காலமாக நீச்சல் அடிக்கிறாய்?"}],"tip":"W-questions: question word + verb + subject: Wie oft gehst du ...? schwimmen gehen = to go swimming."},{"tutor":"Zweimal pro Woche, im Hallenbad bei mir um die Ecke – schon seit drei Jahren. Und sag mal, was isst du gern?","tutor_en":"Twice a week, at the indoor pool around the corner from me – for three years already. And tell me, what do you like to eat?","tutor_ta":"வாரத்துக்கு இரண்டு முறை, என் வீட்டருகே உள்ள உள்ளரங்க நீச்சல் குளத்தில் – மூன்று ஆண்டுகளாக. சொல்லு, உனக்கு என்ன சாப்பிடப் பிடிக்கும்?","task_en":"Say what food you like","task_ta":"உங்களுக்கு என்ன உணவு பிடிக்கும் என்று சொல்லுங்கள்","goal":1,"options":[{"de":"Ich esse gern Dosa und Biryani.","en":"I like eating dosa and biryani.","ta":"எனக்குத் தோசையும் பிரியாணியும் சாப்பிடப் பிடிக்கும்."},{"de":"Am liebsten esse ich indisches Essen.","en":"Most of all I like eating Indian food.","ta":"எல்லாவற்றிலும் எனக்கு இந்திய உணவுதான் மிகவும் பிடிக்கும்."},{"de":"Ich mag Pizza, aber mein Lieblingsessen ist Biryani.","en":"I like pizza, but my favourite food is biryani.","ta":"எனக்கு பீட்சா பிடிக்கும், ஆனால் என் மிகவும் பிடித்த உணவு பிரியாணி."}],"tip":"gern → lieber → am liebsten (like → prefer → like most). das Lieblingsessen = favourite food."},{"tutor":"Lecker! Kochst du auch selbst? Findest du hier alle Zutaten?","tutor_en":"Yummy! Do you cook yourself too? Can you find all the ingredients here?","tutor_ta":"சுவையாக இருக்குமே! நீயே சமைப்பாயா? தேவையான பொருட்கள் எல்லாம் இங்கே கிடைக்கின்றனவா?","task_en":"Say whether you cook and where you buy ingredients","task_ta":"நீங்கள் சமைப்பீர்களா, பொருட்களை எங்கே வாங்குவீர்கள் என்று சொல்லுங்கள்","goal":1,"options":[{"de":"Ja, im indischen Laden finde ich fast alles.","en":"Yes, I find almost everything in the Indian shop.","ta":"ஆம், இந்தியக் கடையில் கிட்டத்தட்ட எல்லாம் கிடைக்கும்."},{"de":"Ja, ich koche oft. Die Gewürze kaufe ich online.","en":"Yes, I cook often. I buy the spices online.","ta":"ஆம், நான் அடிக்கடி சமைப்பேன். மசாலாப் பொருட்களை ஆன்லைனில் வாங்குவேன்."},{"de":"Nicht immer. Curryblätter sind hier schwer zu finden.","en":"Not always. Curry leaves are hard to find here.","ta":"எப்போதும் இல்லை. கறிவேப்பிலை இங்கே கிடைப்பது கடினம்."}],"tip":"schwer zu finden = hard to find (zu + infinitive). Object first for emphasis: Die Gewürze kaufe ich online."},{"tutor":"Und wie gefällt dir das Leben in Deutschland?","tutor_en":"And how do you like life in Germany?","tutor_ta":"ஜெர்மனியில் வாழ்க்கை உனக்கு எப்படிப் பிடித்திருக்கிறது?","task_en":"Say how you like life in Germany","task_ta":"ஜெர்மனியில் வாழ்க்கை உங்களுக்கு எப்படி இருக்கிறது என்று சொல்லுங்கள்","goal":1,"options":[{"de":"Es gefällt mir gut, aber das Wetter ist kalt.","en":"I like it, but the weather is cold.","ta":"எனக்குப் பிடித்திருக்கிறது, ஆனால் வானிலை குளிராக இருக்கிறது."},{"de":"Sehr gut! Die Züge und Parks gefallen mir.","en":"Very much! I like the trains and the parks.","ta":"மிகவும் பிடித்திருக்கிறது! ரயில்களும் பூங்காக்களும் எனக்குப் பிடிக்கும்."},{"de":"Ganz gut, aber ich vermisse meine Familie in Chennai.","en":"Quite well, but I miss my family in Chennai.","ta":"பரவாயில்லை, ஆனால் சென்னையில் இருக்கும் என் குடும்பத்தை நினைத்து ஏங்குகிறேன்."}],"tip":"gefallen + Dativ: Es gefällt mir. Plural thing → plural verb: Die Parks gefallen mir. vermissen = to miss."},{"tutor":"Danke, dass du das erzählst. Möchtest du mich auch noch etwas fragen?","tutor_en":"Thank you for telling me that. Would you like to ask me something too?","tutor_ta":"அதைப் பகிர்ந்ததற்கு நன்றி. நீயும் என்னிடம் ஏதாவது கேட்க விரும்புகிறாயா?","task_en":"Ask your partner a second question","task_ta":"உங்கள் துணையிடம் இரண்டாவது கேள்வியைக் கேளுங்கள்","goal":2,"options":[{"de":"Ja! Woher kommst du?","en":"Yes! Where are you from?","ta":"ஆம்! நீ எங்கிருந்து வருகிறாய்?"},{"de":"Warst du schon mal in Indien?","en":"Have you ever been to India?","ta":"நீ எப்போதாவது இந்தியாவுக்குப் போயிருக்கிறாயா?"},{"de":"Ja. Was ist dein Lieblingsessen?","en":"Yes. What is your favourite food?","ta":"ஆம். உனக்கு மிகவும் பிடித்த உணவு எது?"}],"tip":"Warst du schon mal ...? = Have you ever been ...? (war = past of sein). woher = where from."}],"end":"Ich komme aus Köln, in Indien war ich leider noch nie, und mein Lieblingsessen ist ab heute vielleicht Biryani! Es war sehr schön, mit dir zu sprechen. Bis bald!","end_en":"I'm from Cologne, sadly I've never been to India, and from today my favourite food might be biryani! It was really nice talking to you. See you soon!","end_ta":"நான் கொலோனிலிருந்து வருகிறேன், துரதிர்ஷ்டவசமாக இந்தியாவுக்கு இதுவரை போனதில்லை, இன்றிலிருந்து என் பிடித்த உணவு ஒருவேளை பிரியாணியாக இருக்கலாம்! உன்னுடன் பேசியது மிகவும் மகிழ்ச்சியாக இருந்தது. மீண்டும் சந்திப்போம்!","words":[{"de":"die Freizeit","en":"the free time"},{"de":"das Hobby","en":"the hobby"},{"de":"das Lieblingsessen","en":"the favourite food"},{"de":"die Zutat","en":"the ingredient"},{"de":"das Gewürz","en":"the spice"},{"de":"gefallen","en":"to be pleasing, to like"},{"de":"vermissen","en":"to miss"},{"de":"am liebsten","en":"most of all"}]}
};
